    sessionFilesMovedOrNew: copied,
    scrubbedBaseInstructionBlocks: scrubbedCount,
    lockTimeline: [...locks.entries()]
      .map(([name, v]) => ({ name, ...v, presentAtExit: after250.includes(name) }))
      .sort((a, b) => a.firstSeenMs - b.firstSeenMs),
    locksBeforeRun: [...locksBefore.keys()],
    locksAtExit: after250,
    guardedRealCodexFiles: { before: guardBefore, after: guardAfter,
