// codex-drive.mjs — Phase 10 (Codex kill gate) capture driver.
//
// Runs one `codex exec` probe in a scratch git repo, captures everything Codex
// writes about it, and copies the result under docs/evidence/phase-10/captures/<run>/.
//
// node: builtins only. Writes ONLY to:
//   - %USERPROFILE%\codex-probe\hooks.log        (truncated between runs; we own it)
//   - %USERPROFILE%\codex-probe\scratch\         (the agent's own workspace)
//   - lab/docs/evidence/phase-10/captures/<run>/ (the capture)
// It never writes under %USERPROFILE%\.codex.
//
// NEVER-OPENED LIST (K.11). These paths are named here only so the exclusion is
// auditable; nothing in this file reads them:
//   auth.json  .sandbox-secrets  *.sqlite  *.sqlite-wal  *.sqlite-shm  installation_id
// The snapshot walker below refuses them by name.
//
// Usage:
//   node lab/scripts/codex-drive.mjs <run-name> <prompt-file> [--codex-home <dir>]

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';

const HOME = os.homedir();
const CODEX_DIR = path.join(HOME, '.codex');
const PROBE_DIR = path.join(HOME, 'codex-probe');
const SCRATCH = path.join(PROBE_DIR, 'scratch');
const HOOKS_LOG = path.join(PROBE_DIR, 'hooks.log');
const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const CAPTURES = path.join(HERE, '..', 'docs', 'evidence', 'phase-10', 'captures');

// Files we refuse to open, ever. Matched on basename, case-insensitively.
const NEVER_OPEN_EXACT = new Set(['auth.json', 'installation_id']);
const NEVER_OPEN_DIRS = new Set(['.sandbox-secrets', '.sandbox', '.sandbox-bin', 'cache', 'tmp', '.tmp']);
const NEVER_OPEN_RE = /\.sqlite(-wal|-shm)?$/i;

function refused(name) {
  const n = name.toLowerCase();
  return NEVER_OPEN_EXACT.has(n) || NEVER_OPEN_DIRS.has(n) || NEVER_OPEN_RE.test(n);
}

function sha256File(p) {
  return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
}

/** Recursive (name, size, mtimeMs) listing. Refused entries are listed by name only, never read. */
function snapshot(root) {
  const out = new Map();
  if (!fs.existsSync(root)) return out;
  const walk = (dir, rel) => {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const abs = path.join(dir, e.name);
      const r = rel ? `${rel}/${e.name}` : e.name;
      if (refused(e.name)) { out.set(r, { refused: true }); continue; }
      if (e.isDirectory()) { walk(abs, r); continue; }
      let st;
      try { st = fs.statSync(abs); } catch { continue; }
      out.set(r, { size: st.size, mtimeMs: st.mtimeMs });
    }
  };
  walk(root, '');
  return out;
}

/** Entries that are new, or whose size or mtime moved. */
function changed(before, after) {
  const res = [];
  for (const [rel, a] of after) {
    if (a.refused) continue;
    const b = before.get(rel);
    if (!b || b.refused) { res.push({ rel, kind: 'new', ...a }); continue; }
    if (b.size !== a.size || b.mtimeMs !== a.mtimeMs) {
      res.push({ rel, kind: 'grown', ...a, wasSize: b.size });
    }
  }
  return res;
}

/**
 * Scrub the OpenAI system prompt out of a captured rollout JSONL, in place.
 * Replaces session_meta.payload.base_instructions.text with a digest stub.
 * Every id, call_id, agent_path, ordinal and timestamp stays byte-exact, and
 * encrypted reasoning bytes are left alone (they are G4 evidence).
 */
function scrubRollout(file) {
  const raw = fs.readFileSync(file, 'utf8');
  const eol = raw.includes('\r\n') ? '\r\n' : '\n';
  const lines = raw.split(/\r?\n/);
  let scrubbed = 0;
  const out = lines.map((line) => {
    if (!line.trim()) return line;
    let obj;
    try { obj = JSON.parse(line); } catch { return line; }
    const bi = obj?.payload?.base_instructions;
    if (bi && typeof bi.text === 'string') {
      const bytes = Buffer.byteLength(bi.text, 'utf8');
      obj.payload.base_instructions = {
        scrubbed: true,
        bytes,
        sha256: crypto.createHash('sha256').update(bi.text, 'utf8').digest('hex'),
      };
      scrubbed++;
      return JSON.stringify(obj);
    }
    return line;
  });
  if (scrubbed) fs.writeFileSync(file, out.join(eol), 'utf8');
  return scrubbed;
}

function resolveCodex() {
  const extRoot = path.join(HOME, '.vscode', 'extensions');
  const dirs = fs.readdirSync(extRoot)
    .filter((d) => d.startsWith('openai.chatgpt-'))
    .map((d) => ({ d, p: path.join(extRoot, d, 'bin', 'windows-x86_64', 'codex.exe') }))
    .filter((x) => fs.existsSync(x.p))
    .sort((a, b) => fs.statSync(path.dirname(a.p)).mtimeMs - fs.statSync(path.dirname(b.p)).mtimeMs);
  if (!dirs.length) throw new Error('no codex.exe under ~/.vscode/extensions/openai.chatgpt-*');
  return dirs[dirs.length - 1].p; // newest wins
}

async function main() {
  const [runName, promptFile, ...rest] = process.argv.slice(2);
  if (!runName || !promptFile) {
    console.error('usage: node codex-drive.mjs <run-name> <prompt-file> [--codex-home <dir>]');
    process.exit(2);
  }
  const homeFlag = rest.indexOf('--codex-home');
  const codexHome = homeFlag >= 0 ? rest[homeFlag + 1] : null;

  const codex = resolveCodex();
  const promptText = fs.readFileSync(promptFile, 'utf8');
  const outDir = path.join(CAPTURES, runName);
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(outDir, { recursive: true });

  // The data root this run should write to. With CODEX_HOME set we watch BOTH:
  // the override (does it relocate?) and the real one (is it untouched?).
  const sessionsRoot = path.join(codexHome ?? CODEX_DIR, 'sessions');
  const locksRoot = path.join(codexHome ?? CODEX_DIR, 'thread-writer-locks');

  // K.10 control: hash the two real-.codex files we must not disturb.
  const guarded = ['config.toml', 'hooks.json']
    .map((f) => path.join(CODEX_DIR, f))
    .filter((p) => fs.existsSync(p));
  const guardBefore = Object.fromEntries(guarded.map((p) => [path.basename(p), sha256File(p)]));

  // 2. Truncate the hook log. We own this file.
  fs.writeFileSync(HOOKS_LOG, '');

  // 3. Snapshot before.
  const sessBefore = snapshot(sessionsRoot);
  const realSessBefore = codexHome ? snapshot(path.join(CODEX_DIR, 'sessions')) : sessBefore;
  const locksBefore = snapshot(locksRoot);

  // 4. Spawn. Argument array, no shell.
  const args = ['exec', '--cd', SCRATCH, promptText];
  const env = { ...process.env };
  if (codexHome) { fs.mkdirSync(codexHome, { recursive: true }); env.CODEX_HOME = codexHome; }

  const started = Date.now();
  const child = spawn(codex, args, { windowsHide: true, shell: false, env, cwd: SCRATCH });

  const stdout = [];
  const stderr = [];
  child.stdout.on('data', (d) => stdout.push(d));
  child.stderr.on('data', (d) => stderr.push(d));

  // 4b. Poll thread-writer-locks every 250 ms.
  const locks = new Map(); // name -> {firstSeenMs, lastSeenMs, sizes:Set}
  const poll = setInterval(() => {
    let names = [];
    try { names = fs.readdirSync(locksRoot); } catch { /* dir may not exist yet */ }
    const now = Date.now() - started;
    for (const n of names) {
      const e = locks.get(n);
      if (e) { e.lastSeenMs = now; }
      else { locks.set(n, { firstSeenMs: now, lastSeenMs: now }); }
    }
  }, 250);

  const code = await new Promise((res) => child.on('close', res));
  clearInterval(poll);
  const elapsedMs = Date.now() - started;

  // One last sweep so a lock that outlives the process is visible.
  let after250 = [];
  try { after250 = fs.readdirSync(locksRoot); } catch { /* ignore */ }

  // 5. Snapshot after, copy what moved.
  const sessAfter = snapshot(sessionsRoot);
  const moved = changed(sessBefore, sessAfter);
  const homeOut = path.join(outDir, 'home', '.codex', 'sessions');
  const copied = [];
  for (const m of moved) {
    const src = path.join(sessionsRoot, m.rel);
    const dst = path.join(homeOut, m.rel);
    fs.mkdirSync(path.dirname(dst), { recursive: true });
    fs.copyFileSync(src, dst);
    copied.push({ ...m, dst: path.relative(outDir, dst).replace(/\\/g, '/') });
  }

  // 6. Scrub base_instructions in every copied JSONL.
  let scrubbedCount = 0;
  for (const c of copied) {
    if (c.dst.endsWith('.jsonl')) scrubbedCount += scrubRollout(path.join(outDir, c.dst));
  }

  fs.copyFileSync(HOOKS_LOG, path.join(outDir, 'hooks.log'));
  fs.writeFileSync(path.join(outDir, 'stdout.txt'), Buffer.concat(stdout));
  fs.writeFileSync(path.join(outDir, 'stderr.txt'), Buffer.concat(stderr));

  const guardAfter = Object.fromEntries(guarded.map((p) => [path.basename(p), sha256File(p)]));
  const realSessAfter = codexHome ? snapshot(path.join(CODEX_DIR, 'sessions')) : sessAfter;

  const manifest = {
    run: runName,
    codexBinary: codex,
    promptFile: path.relative(path.join(HERE, '..'), promptFile).replace(/\\/g, '/'),
    promptBytes: Buffer.byteLength(promptText, 'utf8'),
    codexHome: codexHome ?? null,
    sessionsRootWatched: sessionsRoot,
    exitCode: code,
    elapsedMs,
    startedIso: new Date(started).toISOString(),
    sessionFilesMovedOrNew: copied,
    scrubbedBaseInstructionBlocks: scrubbedCount,
    lockTimeline: [...locks.entries()]
      .map(([name, v]) => ({ name, ...v, presentAtExit: after250.includes(name) }))
      .sort((a, b) => a.firstSeenMs - b.firstSeenMs),
    locksBeforeRun: [...locksBefore.keys()],
    locksAtExit: after250,
    guardedRealCodexFiles: { before: guardBefore, after: guardAfter,
      identical: JSON.stringify(guardBefore) === JSON.stringify(guardAfter) },
    realSessionsDirChangedWhileOverridden: codexHome
      ? changed(realSessBefore, realSessAfter).map((c) => c.rel)
      : null,
    hooksLogBytes: fs.statSync(HOOKS_LOG).size,
  };
  fs.writeFileSync(path.join(outDir, 'manifest.json'), JSON.stringify(manifest, null, 2));

  console.log(JSON.stringify({
    run: runName, exitCode: code, elapsedMs,
    sessionFiles: copied.length, scrubbed: scrubbedCount,
    locks: manifest.lockTimeline.length,
    hooksLogBytes: manifest.hooksLogBytes,
    guardedIdentical: manifest.guardedRealCodexFiles.identical,
  }, null, 2));
}

main().catch((e) => { console.error(e); process.exit(1); });

