// stdio[0] MUST be 'ignore', not the default pipe. `codex exec` appends piped
// stdin to the prompt as a <stdin> block, so an open, never-written, never-closed
// pipe makes it block forever before it fires a single hook. Measured 2026-09-02:
// 10 min, hooks.log 0 bytes, no lock file, no session file. 'ignore' gives it a
// closed stdin and it runs.
const started = Date.now();
const child = spawn(codex, args, {
  windowsHide: true, shell: false, env, cwd: SCRATCH,
  stdio: ['ignore', 'pipe', 'pipe'],
});

const stdout = [];
const stderr = [];
child.stdout.on('data', (d) => stdout.push(d));
child.stderr.on('data', (d) => stderr.push(d));

const TIMEOUT_MS = Number(process.env.CODEX_DRIVE_TIMEOUT_MS ?? 900_000);
let timedOut = false;
const killer = setTimeout(() => { timedOut = true; child.kill('SIGKILL'); }, TIMEOUT_MS);

