// codex-analyze.mjs — Phase 10 (Codex kill gate) capture analyser.
//
// Reads the captures written by codex-drive.mjs and prints the measurements
// KILL-GATE.md's DoD items K.2 - K.9 are made of. It derives everything from
// the captured bytes; it never contacts codex and never reads ~/.codex.
//
// node: builtins only.
//
// Usage: node lab/scripts/codex-analyze.mjs [run ...]     (default: every run)

import fs from 'node:fs';
import path from 'node:path';

const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const CAPTURES = path.join(HERE, '..', 'docs', 'evidence', 'phase-10', 'captures');

/** Every rollout JSONL in a run's capture, parsed. Unparseable lines are counted, not dropped silently. */
function loadRun(run) {
  const dir = path.join(CAPTURES, run);
  const sessRoot = path.join(dir, 'home', '.codex', 'sessions');
  const files = [];
  const walk = (d) => {
    if (!fs.existsSync(d)) return;
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith('.jsonl')) files.push(p);
    }
  };
  walk(sessRoot);

  const transcripts = files.map((f) => {
    const lines = fs.readFileSync(f, 'utf8').split(/\r?\n/).filter((l) => l.trim());
    const recs = [];
    let bad = 0;
    for (const l of lines) { try { recs.push(JSON.parse(l)); } catch { bad++; } }
    return { file: path.relative(dir, f).replace(/\\/g, '/'), bytes: fs.statSync(f).size, lines: lines.length, bad, recs };
  });

  // hooks.log: one JSON per line, but the capture command can lose a record's head.
  const hookRaw = fs.existsSync(path.join(dir, 'hooks.log'))
    ? fs.readFileSync(path.join(dir, 'hooks.log'), 'utf8').split(/\r?\n/).filter((l) => l.trim())
    : [];
  const hooks = [];
  const hookBad = [];
  for (const l of hookRaw) {
    try { hooks.push(JSON.parse(l)); } catch { hookBad.push({ bytes: l.length, head: l.slice(0, 60) }); }
  }

  const manifest = fs.existsSync(path.join(dir, 'manifest.json'))
    ? JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8')) : null;
  const stdout = fs.existsSync(path.join(dir, 'stdout.txt'))
    ? fs.readFileSync(path.join(dir, 'stdout.txt'), 'utf8') : '';

  return { run, dir, transcripts, hooks, hookBad, hookRaw, manifest, stdout };
}

/** session_meta payload of a transcript, if it has one. */
function meta(t) {
  const m = t.recs.find((r) => r.type === 'session_meta');
  return m?.payload ?? null;
}

/** Deep search: every [path, value] where the key matches a predicate. */
function findKeys(obj, pred, at = '', out = []) {
  if (obj === null || typeof obj !== 'object') return out;
  for (const [k, v] of Object.entries(obj)) {
    const p = at ? `${at}.${k}` : k;
    if (pred(k)) out.push([p, v]);
    findKeys(v, pred, p, out);
  }
  return out;
}

function K1(runs) {
  console.log('\n=== K.1  binary + version ===');
  for (const r of runs) {
    const versions = new Set();
    for (const t of r.transcripts) { const m = meta(t); if (m?.cli_version) versions.add(m.cli_version); }
    console.log(`${r.run}: manifest binary = ${r.manifest?.codexBinary ?? '(none)'}`);
    console.log(`${r.run}: transcript cli_version = ${[...versions].join(', ') || '(none)'}`);
  }
}

/** Every collaboration spawn call across a run's transcripts. */
function spawnCalls(r) {
  const calls = [];
  for (const t of r.transcripts) {
    for (const rec of t.recs) {
      if (rec.type !== 'response_item') continue;
      const p = rec.payload ?? {};
      const name = p.name ?? '';
      if (!/spawn/i.test(name)) continue;
      let input = p.arguments ?? p.input;
      if (typeof input === 'string') { try { input = JSON.parse(input); } catch { /* keep string */ } }
      calls.push({
        file: t.file, ordinal: rec.ordinal, type: p.type, name,
        call_id: p.call_id, id: p.id,
        task_name: input?.task_name ?? null,
        inputKeys: input && typeof input === 'object' ? Object.keys(input) : null,
      });
    }
  }
  return calls;
}

/** Every spawn RESULT (the object carrying tool_response / output for a spawn call_id). */
function spawnResults(r, callIds) {
  const res = [];
  for (const t of r.transcripts) {
    for (const rec of t.recs) {
      if (rec.type !== 'response_item') continue;
      const p = rec.payload ?? {};
      if (!p.call_id || !callIds.has(p.call_id)) continue;
      if (p.output === undefined && p.result === undefined) continue;
      let out = p.output ?? p.result;
      if (typeof out === 'string') { try { out = JSON.parse(out); } catch { /* keep */ } }
      res.push({ file: t.file, ordinal: rec.ordinal, call_id: p.call_id, type: p.type, output: out });
    }
  }
  return res;
}

function K2(runs) {
  console.log('\n=== K.2  spawn -> child join ===');
  for (const r of runs) {
    const calls = spawnCalls(r);
    const ids = new Set(calls.map((c) => c.call_id));
    const results = spawnResults(r, ids);
    console.log(`\n-- ${r.run}: ${calls.length} spawn call(s), ${results.length} matching result(s)`);
    for (const c of calls) {
      const res = results.find((x) => x.call_id === c.call_id);
      const rTask = res?.output?.task_name ?? (typeof res?.output === 'string' ? res.output.slice(0, 60) : null);
      console.log(`   call ${c.call_id}  name=${c.name}  task_name=${JSON.stringify(c.task_name)}  -> result task_name=${JSON.stringify(rTask)}`);
    }
    // children
    for (const t of r.transcripts) {
      const m = meta(t);
      const sp = m?.source?.subagent?.thread_spawn;
      if (!sp) continue;
      console.log(`   child ${t.file}`);
      console.log(`      id=${m.id}  agent_path=${JSON.stringify(sp.agent_path)}  depth=${sp.depth}`
        + `  parent_thread_id=${sp.parent_thread_id}  nickname=${JSON.stringify(sp.agent_nickname ?? null)}`);
      console.log(`      forked_from_id=${m.forked_from_id ?? null}  thread_source=${JSON.stringify(m.thread_source ?? null)}`
        + `  history_start_ordinal=${m.subagent_history_start_ordinal ?? null}`);
    }
  }
}

function K4(runs) {
  console.log('\n=== K.4  hook tool_use_id <-> transcript call_id ===');
  for (const r of runs) {
    const hookIds = r.hooks.map((h) => h.tool_use_id).filter(Boolean);
    const tIds = new Set();
    for (const t of r.transcripts) {
      for (const rec of t.recs) {
        const c = rec?.payload?.call_id;
        if (c) tIds.add(c);
      }
    }
    const matched = hookIds.filter((i) => tIds.has(i));
    const unmatched = hookIds.filter((i) => !tIds.has(i));
    const prefixes = {};
    for (const i of [...new Set(hookIds)]) { const p = i.split('-')[0].replace(/_.*/, '_'); prefixes[p] = (prefixes[p] ?? 0) + 1; }
    console.log(`${r.run}: hook tool_use_id ${hookIds.length} (distinct ${new Set(hookIds).size}), `
      + `transcript call_id ${tIds.size}; matched ${matched.length}, unmatched ${unmatched.length}`);
    console.log(`   id prefixes: ${JSON.stringify(prefixes)}`);
    if (unmatched.length) console.log(`   unmatched: ${[...new Set(unmatched)].join(', ')}`);
    if (r.hookBad.length) console.log(`   hooks.log UNPARSEABLE lines: ${r.hookBad.length} -> ${JSON.stringify(r.hookBad.map((b) => b.bytes))}`);
  }
}

function K5(runs) {
  console.log('\n=== K.5  fork boundary ===');
  for (const r of runs) {
    const parents = new Map(); // id -> transcript
    for (const t of r.transcripts) { const m = meta(t); if (m?.id) parents.set(m.id, t); }
    for (const t of r.transcripts) {
      const m = meta(t);
      const start = m?.subagent_history_start_ordinal;
      if (start === undefined || start === null) continue;
      const below = t.recs.filter((x) => typeof x.ordinal === 'number' && x.ordinal < start);
      const parentId = m?.source?.subagent?.thread_spawn?.parent_thread_id ?? m?.parent_thread_id;
      const pt = parents.get(parentId);
      let equal = null;
      if (pt) {
        equal = 0;
        for (const rec of below) {
          const pr = pt.recs.find((x) => x.ordinal === rec.ordinal);
          if (pr && JSON.stringify(pr) === JSON.stringify(rec)) equal++;
        }
      }
      console.log(`${r.run} ${t.file}: history_start_ordinal=${start}, records below it=${below.length}, `
        + `byte-equal to parent at same ordinal=${equal ?? 'parent not captured'}`);
      console.log(`   types below: ${JSON.stringify([...new Set(below.map((b) => b.type))])}`);
    }
  }
}

function K6(runs) {
  console.log('\n=== K.6  response_item payload types + reasoning key paths (G4) ===');
  const all = {};
  const reasoningPaths = {};
  for (const r of runs) {
    for (const t of r.transcripts) {
      for (const rec of t.recs) {
        if (rec.type !== 'response_item') continue;
        const ty = rec.payload?.type ?? '(none)';
        all[ty] = (all[ty] ?? 0) + 1;
        for (const [p] of findKeys(rec.payload, (k) => /reason|thought|thinking|encrypted/i.test(k))) {
          reasoningPaths[`payload.${p}`] = (reasoningPaths[`payload.${p}`] ?? 0) + 1;
        }
      }
    }
  }
  console.log('payload.type counts across all captured runs:');
  for (const [k, v] of Object.entries(all).sort((a, b) => b[1] - a[1])) console.log(`   ${v.toString().padStart(5)}  ${k}`);
  console.log('reasoning-bearing key paths:');
  for (const [k, v] of Object.entries(reasoningPaths).sort((a, b) => b[1] - a[1])) console.log(`   ${v.toString().padStart(5)}  ${k}`);
}

function K7(runs) {
  console.log('\n=== K.7  tokens ===');
  const paths = {};
  for (const r of runs) {
    for (const t of r.transcripts) {
      for (const rec of t.recs) {
        for (const [p, v] of findKeys(rec, (k) => /token|usage|cached|context_window/i.test(k))) {
          const key = `${rec.type}.${p}`;
          if (!paths[key]) paths[key] = { n: 0, sample: JSON.stringify(v)?.slice(0, 120) };
          paths[key].n++;
        }
      }
    }
    const m = r.stdout.match(/tokens used[^\n]*/gi);
    if (m) console.log(`${r.run}: stdout -> ${JSON.stringify(m.slice(-3))}`);
  }
  console.log('token/usage key paths in transcripts:');
  const e = Object.entries(paths).sort((a, b) => b[1].n - a[1].n);
  if (!e.length) console.log('   (none)');
  for (const [k, v] of e.slice(0, 40)) console.log(`   ${v.n.toString().padStart(5)}  ${k}  e.g. ${v.sample}`);
}

function K8(runs) {
  console.log('\n=== K.8  liveness by lock ===');
  for (const r of runs) {
    const m = r.manifest;
    if (!m) { console.log(`${r.run}: no manifest`); continue; }
    const threadIds = new Set();
    for (const t of r.transcripts) { const mm = meta(t); if (mm?.id) threadIds.add(mm.id); }
    console.log(`${r.run}: elapsed ${m.elapsedMs} ms; thread ids ${[...threadIds].join(', ') || '(none)'}`);
    console.log(`   locks before run: ${JSON.stringify(m.locksBeforeRun)}`);
    for (const l of m.lockTimeline) {
      const id = l.name.replace(/\.lock$/, '');
      console.log(`   lock ${l.name}  first ${l.firstSeenMs} ms  last ${l.lastSeenMs} ms  atExit=${l.presentAtExit}`
        + `  namesAThreadId=${threadIds.has(id)}`);
    }
    console.log(`   locks at exit: ${JSON.stringify(m.locksAtExit)}`);
  }
}

function K9(runs) {
  console.log('\n=== K.9  inline-output ceiling ===');
  for (const r of runs) {
    for (const t of r.transcripts) {
      for (const rec of t.recs) {
        const p = rec.payload ?? {};
        const out = p.output ?? p.result;
        if (typeof out !== 'string' || out.length < 4096) continue;
        console.log(`${r.run} ${t.file} ordinal ${rec.ordinal} type=${p.type} call_id=${p.call_id}`);
        console.log(`   output string length = ${out.length} bytes(utf8)=${Buffer.byteLength(out, 'utf8')}`);
        console.log(`   head: ${JSON.stringify(out.slice(0, 80))}`);
        console.log(`   tail: ${JSON.stringify(out.slice(-160))}`);
      }
    }
  }
}

function overview(runs) {
  console.log('=== capture overview ===');
  for (const r of runs) {
    console.log(`${r.run}: exit=${r.manifest?.exitCode} timedOut=${r.manifest?.timedOut} `
      + `${r.transcripts.length} transcript(s), ${r.hooks.length} hook record(s) `
      + `(+${r.hookBad.length} unparseable), guardedIdentical=${r.manifest?.guardedRealCodexFiles?.identical}`);
    for (const t of r.transcripts) console.log(`   ${t.file}  ${t.bytes} B  ${t.lines} lines  ${t.bad} unparseable`);
  }
}

const wanted = process.argv.slice(2);
const names = fs.existsSync(CAPTURES)
  ? fs.readdirSync(CAPTURES, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name)
  : [];
const runs = (wanted.length ? wanted : names).map(loadRun);
overview(runs); K1(runs); K2(runs); K4(runs); K5(runs); K6(runs); K7(runs); K8(runs); K9(runs);

