/**
 * K.4. A hook's tool_use_id lives in TWO transcript namespaces, and joining
 * against only one reports a false miss:
 *   - response_item.payload.call_id    — `call_*`, the model-facing tool call
 *   - event_msg.payload.item.id        — `call_*` AND `exec-*`, the item stream
 * A shell call has an `exec-<uuid>` item id and a DIFFERENT `call_<rand>` call_id,
 * so `exec-*` ids can never match the call_id namespace. Measured on the baseline
 * run: 4 of 12 against call_id alone, 12 of 12 against the union.
 */
function K4(runs) {
  console.log('\n=== K.4  hook tool_use_id <-> transcript ids ===');
  for (const r of runs) {
    const hookIds = r.hooks.map((h) => h.tool_use_id).filter(Boolean);
    const callIds = new Set();
    const itemIds = new Set();
    for (const t of r.transcripts) {
      for (const rec of t.recs) {
        if (rec.type === 'response_item' && rec.payload?.call_id) callIds.add(rec.payload.call_id);
        if (rec.type === 'event_msg' && rec.payload?.item?.id) itemIds.add(rec.payload.item.id);
      }
    }
    const union = new Set([...callIds, ...itemIds]);
    const tally = (set) => hookIds.filter((i) => set.has(i)).length;
    const unmatched = [...new Set(hookIds.filter((i) => !union.has(i)))];
    const prefixes = {};
    for (const i of [...new Set(hookIds)]) { const p = /^exec-/.test(i) ? 'exec-' : `${i.split('_')[0]}_`; prefixes[p] = (prefixes[p] ?? 0) + 1; }
    const pct = hookIds.length ? ((tally(union) / hookIds.length) * 100).toFixed(1) : 'n/a';
    console.log(`${r.run}: hook tool_use_id ${hookIds.length} (distinct ${new Set(hookIds).size})`);
    console.log(`   vs response_item.call_id  (${callIds.size} ids): matched ${tally(callIds)}`);
    console.log(`   vs event_msg.item.id      (${itemIds.size} ids): matched ${tally(itemIds)}`);
    console.log(`   vs UNION                  (${union.size} ids): matched ${tally(union)}  = ${pct}%`);
    console.log(`   id prefixes: ${JSON.stringify(prefixes)}`);
    if (unmatched.length) console.log(`   UNMATCHED: ${unmatched.join(', ')}`);
    if (r.hookBad.length) console.log(`   hooks.log UNPARSEABLE lines: ${r.hookBad.length} -> bytes ${JSON.stringify(r.hookBad.map((b) => b.bytes))}`);
  }
}

