// Appends the Phase 10 amendment to PLAN.md, immediately before the "## Parked"
// section, so every closed-phase record above it stays byte-identical.
//
// Slice-based, never String.replace: `.replace()` honours $' in the replacement
// even for a plain-string needle, and has silently duplicated whole documents in
// this repository before.
//
// The amendment text lives in a sibling .md file rather than in a template literal
// here, because writing it inline means escaping backticks in a file that is almost
// entirely backticked identifiers.
import fs from 'node:fs';

const P = new URL('../PLAN.md', import.meta.url);
const SRC = new URL('./phase-10-amendment.md', import.meta.url);

const before = fs.readFileSync(P, 'utf8');
const AMENDMENT = fs.readFileSync(SRC, 'utf8');

const ANCHOR = '## Parked (decided, not built in v0.5.0)';
const i = before.indexOf(ANCHOR);
if (i < 0) throw new Error('anchor not found');
if (before.indexOf(ANCHOR, i + 1) >= 0) throw new Error('anchor not unique');

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;
const eol = before.includes(CRLF) ? CRLF : LF;

// Normalise the insert to whatever the host file already uses, then assert the result
// is not mixed. A raw LF insert into this CRLF file is exactly the silent mixed-ending
// damage CLAUDE.md records, and nothing in this repository's gate would catch it.
const amendment = AMENDMENT.split(CRLF).join(LF).split(LF).join(eol);

const out = before.slice(0, i) + amendment + before.slice(i);

let cr = 0;
let lf = 0;
for (const ch of out) { if (ch === CR) cr++; if (ch === LF) lf++; }
if (eol === CRLF && cr !== lf) throw new Error(`mixed line endings: CR ${cr} LF ${lf}`);

// The insert must not have disturbed anything on either side of it.
if (out.slice(0, i) !== before.slice(0, i)) throw new Error('text above the anchor changed');
if (out.slice(i + amendment.length) !== before.slice(i)) throw new Error('text below the anchor changed');

fs.writeFileSync(P, out, 'utf8');
console.log(`PLAN.md patched; CR ${cr} LF ${lf}; inserted ${amendment.length} chars at ${i}`);

