// Applies the phase-verifier's confirmed findings to KILL-GATE.md, codex-contract.md
// and PLAN.md. Slice-based; every anchor must be present and unique, so a missed
// match fails loudly rather than silently doing nothing. Line endings preserved.
import fs from 'node:fs';

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;

function edit(url, pairs) {
  let t = fs.readFileSync(url, 'utf8');
  const eol = t.includes(CRLF) ? CRLF : LF;
  const before = { cr: 0, lf: 0 };
  for (const ch of t) { if (ch === CR) before.cr++; if (ch === LF) before.lf++; }

  for (const [oldRaw, newRaw] of pairs) {
    // Match against whatever ending the host file uses.
    const old = oldRaw.split(LF).join(eol);
    const next = newRaw.split(LF).join(eol);
    const i = t.indexOf(old);
    if (i < 0) throw new Error(`[${url.pathname}] anchor not found: ${oldRaw.slice(0, 60)}`);
    if (t.indexOf(old, i + 1) >= 0) throw new Error(`[${url.pathname}] anchor not unique: ${oldRaw.slice(0, 60)}`);
    t = t.slice(0, i) + next + t.slice(i + old.length);
  }

  let cr = 0; let lf = 0;
  for (const ch of t) { if (ch === CR) cr++; if (ch === LF) lf++; }
  if (before.cr === before.lf && cr !== lf) throw new Error(`mixed line endings introduced: CR ${cr} LF ${lf}`);
  fs.writeFileSync(url, t, 'utf8');
  console.log(`${url.pathname.split('/').pop()}: ${pairs.length} edit(s), CR ${cr} LF ${lf}`);
}

const KG = new URL('../docs/evidence/phase-10/KILL-GATE.md', import.meta.url);
const CT = new URL('../docs/codex-contract.md', import.meta.url);
const PL = new URL('../PLAN.md', import.meta.url);

// ---------------------------------------------------------------- KILL-GATE.md
edit(KG, [
  // F1 — K.4 totals. long-output was RE-RUN and its row was never re-derived.
  ['`tool_use_id` resolves into the transcript **100% of the time, 66 of 66**.',
   '`tool_use_id` resolves into the transcript **100% of the time, 64 of 64**.'],

  ['| K.4 hook↔transcript match | ≥ 95 % | **100.0 %** (66/66), rest explained: n/a, none unmatched |',
   '| K.4 hook↔transcript match | ≥ 95 % | **100.0 %** (64/64), none unmatched |'],

  ['| baseline | 12 | 4 | 12 | **12 — 100.0 %** |\n| dup-names | 20 | 14 | 17 | **20 — 100.0 %** |\n| parallel-3 | 16 | 10 | 16 | **16 — 100.0 %** |\n| depth-2 | 14 | 12 | 14 | **14 — 100.0 %** |\n| long-output | 4 | 0 | 4 | **4 — 100.0 %** |\n| **total** | **66** | 40 | 63 | **66 — 100.0 %, 0 unmatched** |',
   '| baseline | 12 | 4 | 12 | **12 — 100.0 %** |\n| dup-names | 20 | 14 | 17 | **20 — 100.0 %** |\n| parallel-3 | 16 | 10 | 16 | **16 — 100.0 %** |\n| depth-2 | 14 | 12 | 14 | **14 — 100.0 %** |\n| long-output | 2 | 0 | 2 | **2 — 100.0 %** |\n| **total** | **64** | 40 | 61 | **64 — 100.0 %, 0 unmatched** |'],

  ['alone — the obvious field, the one a reader reaches for first — matches **40 of 66**, and on\n`long-output` it matches **zero**.',
   'alone — the obvious field, the one a reader reaches for first — matches **40 of 64**, and on\n`long-output` it matches **zero of 2**.'],

  ['Recorded as a defect class this repository already knows: a plausible-looking assertion that\nmeasures the wrong thing and reports a clean-looking partial result. The first draft of this\nitem reported "4 of 12, unmatched 8" and would have been read as a Codex deficiency.',
   'Recorded as a defect class this repository already knows: a plausible-looking assertion that\nmeasures the wrong thing and reports a clean-looking partial result. The first draft of this\nitem reported "4 of 12, unmatched 8" and would have been read as a Codex deficiency.\n\n**And the totals in this table were themselves wrong until `phase-verifier` re-derived them.**\nThe `long-output` run was **re-run** after its first attempt measured nothing (K.9), and its row\nhere was copied from the analysis of the *discarded* attempt: 4 where the committed capture holds\n2. Three totals and two sentences carried the error. **This is this repository\'s most-recorded\ndefect — a number written from inside the phase that changed it — committed in the very item\nwhose subject is a number that looks right and is not.** The capture was replaced; the figure\nderived from it was not.'],

  // F2 — forked_from_id is ABSENT, not null.
  ['| dup-names `/root/dup/dup` | **absent** | — | spawned `fork_turns: "none"`, `forked_from_id: null` |',
   '| dup-names `/root/dup/dup` | **absent** | — | spawned `fork_turns: "none"`; `forked_from_id` **also absent** |'],

  ['**When the field is absent, drop nothing** — `/root/dup/dup` is the\nmeasured case and an engine that treats absence as `0` or as "drop everything" gets it wrong in\nopposite directions.',
   '**When the field is absent, drop nothing** — `/root/dup/dup` is the\nmeasured case and an engine that treats absence as `0` or as "drop everything" gets it wrong in\nopposite directions.\n\n**`forked_from_id` is ABSENT on that thread, not `null`.** Measured: `\'forked_from_id\' in payload`\nis `false`. An earlier draft of this file wrote `null`, and `phase-verifier` caught it. That is\nthis repository\'s single most-cited constraint — *CC omits the field rather than sending a\nsentinel; **absence of the key is the signal*** — being mis-documented for a third engine. An\nengine written against `forked_from_id === null` reads `undefined`, takes the wrong branch, and\nthrows nothing.'],

  // F3 — K.6 census: 12/12, not 13/13.
  ['| 13 | `custom_tool_call` |\n| 13 | `custom_tool_call_output` |',
   '| 12 | `custom_tool_call` |\n| 12 | `custom_tool_call_output` |'],

  ['| 19 | `agent_message` |',
   '| 19 | `agent_message` |\n| **211** | **total `response_item` records — the column sums to this exactly** |'],

  // F4 — K.11 line numbers and control counts, both written before their own change.
  ['`grep` of `lab/scripts/codex-drive.mjs` for each name returns **only the header comment and the\nexclusion list** — lines 14, 35, 36, 37. Nothing reads them.',
