// Applies the phase-verifier's confirmed findings to KILL-GATE.md, codex-contract.md
// and PLAN.md. Slice-based; every anchor must be present and unique, so a missed
// match fails loudly rather than silently doing nothing. Line endings preserved.
import fs from 'node:fs';

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;

function edit(url, pairs) {
  let t = fs.readFileSync(url, 'utf8');
  const eol = t.includes(CRLF) ? CRLF : LF;
  const before = { cr: 0, lf: 0 };
  for (const ch of t) { if (ch === CR) before.cr++; if (ch === LF) before.lf++; }

  for (const [oldRaw, newRaw] of pairs) {
    // Match against whatever ending the host file uses.
    const old = oldRaw.split(LF).join(eol);
    const next = newRaw.split(LF).join(eol);
    const i = t.indexOf(old);
    if (i < 0) throw new Error(`[${url.pathname}] anchor not found: ${oldRaw.slice(0, 60)}`);
    if (t.indexOf(old, i + 1) >= 0) throw new Error(`[${url.pathname}] anchor not unique: ${oldRaw.slice(0, 60)}`);
    t = t.slice(0, i) + next + t.slice(i + old.length);
  }

  let cr = 0; let lf = 0;
  for (const ch of t) { if (ch === CR) cr++; if (ch === LF) lf++; }
  if (before.cr === before.lf && cr !== lf) throw new Error(`mixed line endings introduced: CR ${cr} LF ${lf}`);
  fs.writeFileSync(url, t, 'utf8');
  console.log(`${url.pathname.split('/').pop()}: ${pairs.length} edit(s), CR ${cr} LF ${lf}`);
}

