// byte 0; nothing already in the file is touched. Line endings normalised to the
// host file's, and the result asserted non-mixed.
import fs from 'node:fs';

const H = new URL('../HANDOVER.md', import.meta.url);
const SRC = process.argv[2];

const before = fs.readFileSync(H, 'utf8');
let section = fs.readFileSync(SRC, 'utf8');

// Two corrections to the draft, applied here so the scratch draft and the record
// cannot drift apart: the dangling article left by the byte-count fix, and the
// over-broad "no byte written" claim the verifier correctly rejected.
const fixes = [
  ['another entirely would look identical to a missing event. It is **not** a length limit: a\nlargest intact record is **41,918 chars / 41,922 bytes**.',
   'another entirely would look identical to a missing event. It is **not** a length limit — the\nlargest intact record is **41,918 chars / 41,922 bytes**.'],
  ['**No engine code. No public fixtures. No byte written under the Codex data directory** — every\nrun hashes `config.toml` and `hooks.json` before and after, and `guardedIdentical` is `true` on\n6 of 6.',
   '**No engine code. No public fixtures.** On writes under the Codex data directory, the precise\nclaim rather than the broad one: `config.toml` and `hooks.json` are hashed before and after every\nrun and are identical on **6 of 6**, and the real `.codex\\sessions` was diffed across the\n`CODEX_HOME` run and came back unchanged. **Everything beyond those is a reading of the driver\'s\nsource, not a filesystem-wide check** — `phase-verifier` was right to say the two-file hash does\nnot carry a blanket "nothing was written", and the contract now says so too.'],
];
for (const [a, b] of fixes) {
  const i = section.indexOf(a);
  if (i < 0) throw new Error(`draft fix anchor missing: ${a.slice(0, 50)}`);
  section = section.slice(0, i) + b + section.slice(i + a.length);
}

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;
const eol = before.includes(CRLF) ? CRLF : LF;
section = section.split(CRLF).join(LF).split(LF).join(eol);

const out = section + eol + before;

let cr = 0; let lf = 0;
for (const ch of out) { if (ch === CR) cr++; if (ch === LF) lf++; }
if (eol === CRLF && cr !== lf) throw new Error(`mixed line endings: CR ${cr} LF ${lf}`);
if (!out.endsWith(before)) throw new Error('existing HANDOVER.md content was altered');

fs.writeFileSync(H, out, 'utf8');
console.log(`HANDOVER.md: prepended ${section.length} chars; CR ${cr} LF ${lf}`);

