// Step 2: archive the v0.5.0 plan and install the v0.6.0 plan.
//
// The brief expected PLAN-v0.6.0.md as a separate file at the repo root. It was
// never created; the v0.6.0 plan arrived appended to the end of lab/PLAN.md
// instead. This performs the same end state as a split, and PROVES the archive
// half is byte-identical to the committed PLAN.md rather than asserting it.
//
// Slice-based. Line endings preserved and asserted non-mixed on both outputs.
import fs from 'node:fs';
import crypto from 'node:crypto';
import { execSync } from 'node:child_process';

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;

const sha = (buf) => crypto.createHash('sha256').update(buf).digest('hex');
const endings = (s) => {
  let cr = 0; let lf = 0;
  for (const ch of s) { if (ch === CR) cr++; if (ch === LF) lf++; }
  return { cr, lf, mixed: cr !== 0 && cr !== lf };
};

const MARKER = '# PLAN.md — Agent Deck (v0.6.0: third observation engine, Codex)';

const current = fs.readFileSync('PLAN.md', 'utf8');
const i = current.indexOf(MARKER);
if (i < 0) throw new Error('v0.6.0 marker not found');
if (current.indexOf(MARKER, i + 1) >= 0) throw new Error('v0.6.0 marker is not unique');

const archive = current.slice(0, i).replace(/(\r?\n)+$/, CRLF);
const install = current.slice(i);

// --- byte-identity proof -----------------------------------------------------
// The committed blob is LF (git normalises on the way in); the worktree is CRLF.
// Compare like with like by converting the blob to the worktree's ending.
const committedLF = execSync('git show HEAD:PLAN.md', { encoding: 'utf8', maxBuffer: 1e8 });
const committedAsWorktree = committedLF.split(CRLF).join(LF).split(LF).join(CRLF).replace(/(\r?\n)+$/, CRLF);

const shaBefore = sha(Buffer.from(committedAsWorktree, 'utf8'));
const shaAfter = sha(Buffer.from(archive, 'utf8'));
console.log('sha256 committed PLAN.md (worktree form):', shaBefore);
console.log('sha256 archive content                  :', shaAfter);
if (shaBefore !== shaAfter) throw new Error('ARCHIVE IS NOT BYTE-IDENTICAL — aborting');
console.log('byte-identical: YES');

const eA = endings(archive);
const eI = endings(install);
if (eA.mixed || eI.mixed) throw new Error(`mixed line endings: archive ${JSON.stringify(eA)} install ${JSON.stringify(eI)}`);

fs.mkdirSync('docs', { recursive: true });
fs.writeFileSync('docs/PLAN-v0.5.0.md', archive, 'utf8');
fs.writeFileSync('PLAN.md', install, 'utf8');

console.log(`archive: docs/PLAN-v0.5.0.md  ${Buffer.byteLength(archive, 'utf8')} bytes  CR ${eA.cr} LF ${eA.lf}`);
console.log(`install: PLAN.md              ${Buffer.byteLength(install, 'utf8')} bytes  CR ${eI.cr} LF ${eI.lf}`);
console.log('PLAN.md line 1:', install.split(/\r?\n/)[0]);

