}

const doc = { hooks };
fs.writeFileSync(OUT, `${JSON.stringify(doc, null, 2)}\n`, 'utf8');

console.log(`README hook commands found: ${matches.length}, distinct: ${distinct.length}`);
console.log(`command bytes: ${Buffer.byteLength(command, 'utf8')}`);
console.log(`events written: ${EVENTS.length} -> ${EVENTS.join(' ')}`);
console.log(`wrote: lab/codex-hooks.json (${fs.statSync(OUT).size} bytes)`);

