// Records the hook configuration being retired, BEFORE the user pastes the new
// six-event block. Read-only against ~/.codex; writes only into lab/.
//
// The retired command embeds an absolute home path, so it is redacted to
// %USERPROFILE% here — the contract must not carry identity (G8).
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';

const home = os.homedir();
const hooksJson = path.join(home, '.codex', 'hooks.json');
const configToml = path.join(home, '.codex', 'config.toml');

const j = JSON.parse(fs.readFileSync(hooksJson, 'utf8'));

const commands = new Set();
for (const arr of Object.values(j.hooks)) {
  for (const group of arr) for (const h of group.hooks) commands.add(h.command);
}
if (commands.size !== 1) throw new Error(`expected 1 retired command, found ${commands.size}`);
const raw = [...commands][0];

// Redact both slash forms of the home path.
const homeBack = home.split('/').join('\\');
const homeFwd = home.split('\\').join('/');
const redacted = raw.split(homeBack).join('%USERPROFILE%').split(homeFwd).join('%USERPROFILE%');
if (redacted.includes(homeBack) || redacted.includes(homeFwd)) throw new Error('redaction failed');

const toml = fs.readFileSync(configToml, 'utf8');

const out = {
  note: 'Measured before the six-event loopback block was pasted. Retired by Phase 1 DoD 1.3.',
  retiredCommandRedacted: redacted,
  retiredCommandBytes: Buffer.byteLength(raw, 'utf8'),
  retiredEventCount: Object.keys(j.hooks).length,
  retiredEvents: Object.keys(j.hooks),
  trustedHashEntries: (toml.match(/trusted_hash/g) ?? []).length,
  hooksJsonSha256: crypto.createHash('sha256').update(fs.readFileSync(hooksJson)).digest('hex'),
  configTomlSha256: crypto.createHash('sha256').update(fs.readFileSync(configToml)).digest('hex'),
};

const dest = new URL('../docs/evidence/phase-1/retired-hook-config.json', import.meta.url);
fs.mkdirSync(new URL('../docs/evidence/phase-1/', import.meta.url), { recursive: true });
fs.writeFileSync(dest, `${JSON.stringify(out, null, 2)}\n`, 'utf8');
console.log(JSON.stringify(out, null, 2));

