// Verifies the pasted six-event block: content equivalence with lab/codex-hooks.json
// (ignoring formatting), and whether config.toml's trust actually refreshed.
// Read-only against ~/.codex.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';

const home = os.homedir();
const hj = path.join(home, '.codex', 'hooks.json');
const ct = path.join(home, '.codex', 'config.toml');

const liveRaw = fs.readFileSync(hj);
const mineRaw = fs.readFileSync(new URL('../codex-hooks.json', import.meta.url));

const live = JSON.parse(liveRaw.toString('utf8'));
const mine = JSON.parse(mineRaw.toString('utf8'));

console.log('byte-identical      :', liveRaw.equals(mineRaw));
console.log('semantically equal  :', JSON.stringify(live) === JSON.stringify(mine));
console.log('live bytes / mine   :', liveRaw.length, '/', mineRaw.length);

// Where do the bytes differ, if they do?
const liveTxt = liveRaw.toString('utf8');
const mineTxt = mineRaw.toString('utf8');
const cr = (s) => (s.match(/\r/g) ?? []).length;
console.log('CR count live/mine  :', cr(liveTxt), '/', cr(mineTxt));
console.log('trailing newline    : live', JSON.stringify(liveTxt.slice(-2)), 'mine', JSON.stringify(mineTxt.slice(-2)));

// Trust state: which events have a trusted_hash, and did config.toml move?
const toml = fs.readFileSync(ct, 'utf8');
const RECORDED_BEFORE = '90757773c1d4d1d16929b7459654f62c0e97485958c190713328b68985020a68';
const nowSha = crypto.createHash('sha256').update(fs.readFileSync(ct)).digest('hex');
console.log('\nconfig.toml sha256 before paste :', `${RECORDED_BEFORE.slice(0, 16)}…`);
console.log('config.toml sha256 now          :', `${nowSha.slice(0, 16)}…`);
console.log('config.toml CHANGED             :', nowSha !== RECORDED_BEFORE);

// Map event -> trusted_hash, in file order.
const entries = [...toml.matchAll(/hooks\.state\.'[^']*:([a-z_]+):\d+:\d+'\]\s*\ntrusted_hash = "sha256:([0-9a-f]+)"/g)]
  .map((m) => ({ event: m[1], hash: m[2] }));
const byEvent = new Map();
for (const e of entries) byEvent.set(e.event, e.hash);

const LIVE_SIX = ['session_start', 'pre_tool_use', 'post_tool_use', 'subagent_start', 'subagent_stop', 'stop'];
const distinctHashes = new Set(LIVE_SIX.map((e) => byEvent.get(e)).filter(Boolean));
console.log('\ntrusted entries total           :', entries.length);
console.log('the six live events have a hash :', LIVE_SIX.filter((e) => byEvent.has(e)).length, 'of 6');
console.log('distinct hashes across the six  :', distinctHashes.size, '(1 = all six trust the same command, as expected)');
for (const e of LIVE_SIX) console.log(`   ${e.padEnd(16)} ${byEvent.get(e)?.slice(0, 16) ?? '(MISSING)'}…`);

const stale = entries.filter((e) => !LIVE_SIX.includes(e.event)).map((e) => e.event);
console.log('stale entries for dropped events:', stale.length, stale.join(' '));

