// Phase 1 DoD 1.3 — the clean hook capture path.
//
// Phase 0 captured hooks with `cmd /c findstr /r .* >> hooks.log`, which loses
// records under concurrent appends (1 of 101 measured, head truncated). This
// replaces it with THE SHIPPED LISTENER: `src/hooks/listener.ts`, the same module
// the extension runs, bound to the same port the shipped README block names.
//
// That is the point of the arrangement, not an implementation detail — the
// harvest pins what the shipped hook block delivers to the shipped listener.
// Capturing through a bespoke reader would prove something the product does not do.
//
// PORT POLICY, and why there is no fallback. `DEFAULT_HOOK_PORT` (47821) is named
// LITERALLY in the pasted hook command. If something else holds it, binding a
// different port captures NOTHING — the hooks still POST to 47821, into whatever
// is listening there. So a collision is a hard, loud failure. Never "fall back".
//
// node: builtins only, plus the repo's own esbuild to compile the TS listener.

import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const require = createRequire(import.meta.url);

const LAB = path.dirname(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')));
const REPO = path.dirname(LAB);
const LISTENER_TS = path.join(REPO, 'src', 'hooks', 'listener.ts');
// lab/dist is gitignored (lab/.gitignore), so the bundle never reaches a commit.
const BUNDLE_DIR = path.join(LAB, 'dist');
const BUNDLE = path.join(BUNDLE_DIR, 'hook-listener.bundle.mjs');

/** Compile the real listener to an importable ESM bundle. */
export async function buildListenerBundle() {
  if (!fs.existsSync(LISTENER_TS)) throw new Error(`listener source missing: ${LISTENER_TS}`);
  const esbuild = require('esbuild');
  fs.mkdirSync(BUNDLE_DIR, { recursive: true });
  await esbuild.build({
    entryPoints: [LISTENER_TS],
    outfile: BUNDLE,
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node22',
    logLevel: 'silent',
  });
  return BUNDLE;
}

/**
 * Start the shipped listener and append every event it accepts to `outFile`,
 * one JSON object per line, each carrying the listener's own `seq` and
 * `receivedAt` plus the payload exactly as received.
 *
 * Throws with a diagnosis if the port is held.
 */
export async function startHookCapture({ port = 47821, outFile }) {
  if (!outFile) throw new Error('outFile is required');

  const bundlePath = await buildListenerBundle();
  const mod = await import(`${pathToFileURL(bundlePath).href}?t=${Date.now()}`);
  const { HookListener, DEFAULT_HOOK_PORT, isHookListenerBindError } = mod;

  if (port !== DEFAULT_HOOK_PORT) {
    // Not fatal, but it means the pasted command is pointing elsewhere.
    console.warn(`WARNING: capturing on ${port}, but the shipped hook block names ${DEFAULT_HOOK_PORT}.`);
  }

  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  const stream = fs.createWriteStream(outFile, { flags: 'w' });

  let count = 0;
  const byEvent = Object.create(null);

  const listener = new HookListener({
    port,
    onEvent: (e) => {
      count += 1;
      const name = e.eventName ?? '(none)';
      byEvent[name] = (byEvent[name] ?? 0) + 1;
      // One JSON per line. `raw` is the payload unmodified (listener contract).
      stream.write(`${JSON.stringify({
        seq: e.seq,
        receivedAt: e.receivedAt,
        eventName: e.eventName,
        eventNameConfirmed: e.eventNameConfirmed,
        sessionId: e.sessionId,
        agentId: e.agentId,
        isMainThread: e.isMainThread,
        toolUseId: e.toolUseId,
        toolName: e.toolName,
        raw: e.raw,
      })}\n`);
    },
  });

  try {
    await listener.start();
  } catch (err) {
    stream.end();
    if (isHookListenerBindError?.(err) || err?.code === 'EADDRINUSE' || /EADDRINUSE/.test(String(err))) {
      throw new Error(
        `port ${port} is already in use, so this harvest would capture NOTHING.\n`
        + `The pasted Codex hook command names ${port} literally, so its POSTs go to whatever holds it.\n`
        + 'On this machine that is normally the Agent Deck extension inside VS Code.\n'
        + 'Free the port (disable/stop the extension, or close that window) and re-run. '
        + 'Binding a different port is NOT a fix.',
      );
    }
    throw err;
  }

  return {
    port,
    get count() { return count; },
    get byEvent() { return { ...byEvent }; },
    async stop() {
      await listener.stop();
      await new Promise((res) => stream.end(res));
      return { count, byEvent: { ...byEvent } };
    },
  };
}

