// Rewires codex-drive.mjs from the retired `hooks.log` capture to the shipped
// listener. Slice-based, unique anchors, fails loudly on a miss.
import fs from 'node:fs';

const P = new URL('./codex-drive.mjs', import.meta.url);
let t = fs.readFileSync(P, 'utf8');

function rep(old, next) {
  const i = t.indexOf(old);
  if (i < 0) throw new Error(`anchor not found: ${old.slice(0, 60)}`);
  if (t.indexOf(old, i + 1) >= 0) throw new Error(`anchor not unique: ${old.slice(0, 60)}`);
  t = t.slice(0, i) + next + t.slice(i + old.length);
}

rep(`//   - %USERPROFILE%\\codex-probe\\hooks.log        (truncated between runs; we own it)`,
    `//   - lab/dist/hook-listener.bundle.mjs          (compiled listener; gitignored)`);

rep(`const HOOKS_LOG = path.join(PROBE_DIR, 'hooks.log');`,
    `// Phase 1: hooks are captured through the SHIPPED listener on the SHIPPED port,
// not by appending to a file. The retired path was
// \`cmd /c findstr /r .* >> hooks.log\`, which lost 1 record of 101 under
// concurrent appends. See scripts/codex-hook-listener.mjs.
const HOOK_PORT = Number(process.env.CODEX_DRIVE_HOOK_PORT ?? 47821);`);

rep(`import { spawn } from 'node:child_process';`,
    `import { spawn } from 'node:child_process';

import { startHookCapture } from './codex-hook-listener.mjs';`);

// Replace "truncate the log" with "start the listener".
rep(`  // 2. Truncate the hook log. We own this file.
  fs.writeFileSync(HOOKS_LOG, '');`,
    `  // 2. Start the shipped listener BEFORE Codex runs, so SessionStart is not
  // missed. A held port is fatal here on purpose: the pasted hook command names
  // the port literally, so capturing on another one captures nothing.
  const hookStreamFile = path.join(outDir, 'hook-stream.jsonl');
  const capture = await startHookCapture({ port: HOOK_PORT, outFile: hookStreamFile });`);

rep(`  fs.copyFileSync(HOOKS_LOG, path.join(outDir, 'hooks.log'));`,
    `  const hookSummary = await capture.stop();`);

rep(`    hooksLogBytes: fs.statSync(HOOKS_LOG).size,`,
    `    hookPort: HOOK_PORT,
    hookEventsCaptured: hookSummary.count,
    hookEventsByName: hookSummary.byEvent,
    hookStreamBytes: fs.existsSync(hookStreamFile) ? fs.statSync(hookStreamFile).size : 0,`);

rep(`    hooksLogBytes: manifest.hooksLogBytes,`,
    `    hookEventsCaptured: hookSummary.count,
    hookEventsByName: hookSummary.byEvent,`);

fs.writeFileSync(P, t, 'utf8');
console.log('codex-drive.mjs rewired to the listener capture path');

