1	// codex-drive.mjs — Phase 10 (Codex kill gate) capture driver.
2	//
3	// Runs one `codex exec` probe in a scratch git repo, captures everything Codex
4	// writes about it, and copies the result under docs/evidence/phase-10/captures/<run>/.
5	//
6	// node: builtins only. Writes ONLY to:
7	//   - lab/dist/hook-listener.bundle.mjs          (compiled listener; gitignored)
8	//   - %USERPROFILE%\codex-probe\scratch\         (the agent's own workspace)
9	//   - lab/docs/evidence/phase-10/captures/<run>/ (the capture)
10	// It never writes under %USERPROFILE%\.codex.
11	//
12	// NEVER-OPENED LIST (K.11). These paths are named here only so the exclusion is
13	// auditable; nothing in this file reads them:
14	//   auth.json  .sandbox-secrets  *.sqlite  *.sqlite-wal  *.sqlite-shm  installation_id  cap_sid
15	// The snapshot walker below refuses them by name. `cap_sid` was not in the brief's
16	// list; it was found by running the predicate over the real directory (KILL-GATE K.11)
17	// and is refused because an unexplained file whose name reads as a security identifier
18	// is not something to walk into.
19	//
20	// Usage:
21	//   node lab/scripts/codex-drive.mjs <run-name> <prompt-file> [--codex-home <dir>]
22	
23	import fs from 'node:fs';
24	import path from 'node:path';
25	import os from 'node:os';
26	import crypto from 'node:crypto';
27	import { spawn } from 'node:child_process';
28	
29	import { startHookCapture } from './codex-hook-listener.mjs';
30	
31	const HOME = os.homedir();
32	const CODEX_DIR = path.join(HOME, '.codex');
33	const PROBE_DIR = path.join(HOME, 'codex-probe');
34	const SCRATCH = path.join(PROBE_DIR, 'scratch');
35	// Phase 1: hooks are captured through the SHIPPED listener on the SHIPPED port,
36	// not by appending to a file. The retired path was
37	// `cmd /c findstr /r .* >> hooks.log`, which lost 1 record of 101 under
38	// concurrent appends. See scripts/codex-hook-listener.mjs.
39	const HOOK_PORT = Number(process.env.CODEX_DRIVE_HOOK_PORT ?? 47821);
40	const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
41	const CAPTURES = path.join(HERE, '..', 'docs', 'evidence', 'phase-10', 'captures');
42	
43	// Files we refuse to open, ever. Matched on basename, case-insensitively.
44	const NEVER_OPEN_EXACT = new Set(['auth.json', 'installation_id', 'cap_sid']);
45	const NEVER_OPEN_DIRS = new Set(['.sandbox-secrets', '.sandbox', '.sandbox-bin', 'cache', 'tmp', '.tmp']);
46	const NEVER_OPEN_RE = /\.sqlite(-wal|-shm)?$/i;
47	
48	function refused(name) {
49	  const n = name.toLowerCase();
50	  return NEVER_OPEN_EXACT.has(n) || NEVER_OPEN_DIRS.has(n) || NEVER_OPEN_RE.test(n);
51	}
52	
53	function sha256File(p) {
54	  return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
55	}
56	
57	/** Recursive (name, size, mtimeMs) listing. Refused entries are listed by name only, never read. */
58	function snapshot(root) {
59	  const out = new Map();
60	  if (!fs.existsSync(root)) return out;
61	  const walk = (dir, rel) => {
62	    let entries;
63	    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
64	    for (const e of entries) {
65	      const abs = path.join(dir, e.name);
66	      const r = rel ? `${rel}/${e.name}` : e.name;
67	      if (refused(e.name)) { out.set(r, { refused: true }); continue; }
68	      if (e.isDirectory()) { walk(abs, r); continue; }
69	      let st;
70	      try { st = fs.statSync(abs); } catch { continue; }
71	      out.set(r, { size: st.size, mtimeMs: st.mtimeMs });
72	    }
73	  };
74	  walk(root, '');
75	  return out;
76	}
77	
78	/** Entries that are new, or whose size or mtime moved. */
