// DoD 1.1 — insert the Codex amendment into agent-deck-spec.md.
//
// PLACEMENT IS LOAD-BEARING, not cosmetic. `src/release/readme.test.ts` slices the
// version-posture amendment as "its heading through END OF DOCUMENT" and asserts
// `amendment.includes('\n## ') === false` — i.e. it must remain the last `##`
// section in the file. Appending after it turns that test red AND folds Codex prose
// into the section the version-posture guards scan. The OpenCode amendment is placed
// before it for the same reason. So: insert immediately BEFORE the version-posture
// heading.
//
// Slice-based, unique anchor, line endings preserved and asserted.
import fs from 'node:fs';

const SPEC = new URL('../agent-deck-spec.md', import.meta.url);
const SRC = process.argv[2];
if (!SRC) throw new Error('usage: node insert-spec-amendment.mjs <amendment.md>');

const before = fs.readFileSync(SPEC, 'utf8');
let block = fs.readFileSync(SRC, 'utf8');

const ANCHOR = '## Amendment 2026-08-26 — Version posture';
const i = before.indexOf(ANCHOR);
if (i < 0) throw new Error('version-posture anchor not found');
if (before.indexOf(ANCHOR, i + 1) >= 0) throw new Error('version-posture anchor not unique');

const HEADING = '## Amendment 2026-09-02 — Third observation source: Codex';
if (before.includes(HEADING)) throw new Error('the Codex amendment is already present');

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;
const eol = before.includes(CRLF) ? CRLF : LF;
block = block.split(CRLF).join(LF).split(LF).join(eol);
if (!block.endsWith(eol + eol)) block = `${block.replace(/(\r?\n)+$/, '')}${eol}${eol}`;

const out = before.slice(0, i) + block + before.slice(i);

let cr = 0; let lf = 0;
for (const ch of out) { if (ch === CR) cr++; if (ch === LF) lf++; }
if (eol === CRLF && cr !== lf) throw new Error(`mixed line endings: CR ${cr} LF ${lf}`);
if (out.slice(0, i) !== before.slice(0, i)) throw new Error('text above the anchor changed');
if (out.slice(i + block.length) !== before.slice(i)) throw new Error('text below the anchor changed');

// The guard this placement exists to satisfy, asserted here too rather than
// discovered later by the suite.
const vpStart = out.indexOf(ANCHOR);
if (out.slice(vpStart).includes(`${eol}## `)) {
  throw new Error('the version-posture amendment is no longer the last ## section');
}

fs.writeFileSync(SPEC, out, 'utf8');
console.log(`agent-deck-spec.md: inserted ${block.length} chars before the version-posture amendment`);
console.log(`CR ${cr} LF ${lf}`);

