// Inserts the Phase 1 constraints into CLAUDE.md's "Constraints discovered the
// hard way" list, immediately before "## Working process". Slice-based, CRLF
// preserved and asserted, anchors unique.
//
// This exists because the Phase 1 handoff DRAFT claimed these were already in
// CLAUDE.md when they were only in a scratch file. phase-verifier caught it.
import fs from 'node:fs';

const C = new URL('../CLAUDE.md', import.meta.url);
const SRC = process.argv[2];
if (!SRC) throw new Error('usage: node add-p1-constraints.mjs <bullets.md>');

const before = fs.readFileSync(C, 'utf8');
const bullets = fs.readFileSync(SRC, 'utf8');

const ANCHOR = '## Working process';
const i = before.indexOf(ANCHOR);
if (i < 0) throw new Error('anchor not found');
if (before.indexOf(ANCHOR, i + 1) >= 0) throw new Error('anchor not unique');

// Refuse to double-insert.
const PROBE = 'A CAPTURE THAT BINDS A DIFFERENT PORT';
if (before.includes(PROBE)) throw new Error('these constraints are already present');

const CR = String.fromCharCode(13);
const LF = String.fromCharCode(10);
const CRLF = CR + LF;
const eol = before.includes(CRLF) ? CRLF : LF;

const block = (`${bullets.trimEnd()}${LF}${LF}`).split(CRLF).join(LF).split(LF).join(eol);
const out = before.slice(0, i) + block + before.slice(i);

let cr = 0; let lf = 0;
for (const ch of out) { if (ch === CR) cr++; if (ch === LF) lf++; }
if (eol === CRLF && cr !== lf) throw new Error(`mixed line endings: CR ${cr} LF ${lf}`);
if (out.slice(0, i) !== before.slice(0, i)) throw new Error('text above the anchor changed');
if (out.slice(i + block.length) !== before.slice(i)) throw new Error('text below the anchor changed');

fs.writeFileSync(C, out, 'utf8');
console.log(`CLAUDE.md: inserted ${block.length} chars; CR ${cr} LF ${lf}`);

