1	/**
2	 * capture-codex.mjs — turn a lab capture into a committable Codex fixture corpus.
3	 *
4	 * Phase 1 DoD 1.3. The counterpart of `scripts/capture-opencode.mjs`, and it holds
5	 * the same line: the LAB holds unredacted captures, `fixtures/` holds redacted ones,
6	 * and this script is the only door between them.
7	 *
8	 * WHAT IT READS. Exactly two things per run, both produced by
9	 * `lab/scripts/codex-drive.mjs`:
10	 *   - `home/.codex/sessions/**\/*.jsonl`   the rollout transcripts
11	 *   - `hook-stream.jsonl`                  the listener's own record of the hook POSTs
12	 * It never reads a live `~/.codex`, never opens a `*.sqlite`, and never touches
13	 * `auth.json`, `.sandbox-secrets/`, `installation_id` or `cap_sid` (G10).
14	 *
15	 * WHAT IT REFUSES. G8 is enforced here, not hoped for, and in TWO places:
16	 *   - if ANY transcript's `session_meta.payload.cwd` is not the scratch repo, the
17	 *     run aborts and writes nothing;
18	 *   - if the hook stream is MOSTLY foreign (see below), the run aborts too.
19	 * A corpus is only committable when every session in it belongs to the throwaway
20	 * probe repo.
21	 *
22	 * WHY THE HOOK STREAM NEEDS FILTERING AT ALL. Both engines POST to ONE loopback
23	 * listener (decision D0.3), and this repository's own Claude Code hook block is live
24	 * and unconditional. So while a harvest holds the port, Claude Code's own tool calls
25	 * land in the Codex capture. Measured on the Phase 1 captures: 18 foreign records
26	 * across 4 of 9 runs, one batch injected by a Claude Code SUBAGENT's worktree. Those
27	 * records carry real developer paths, so they would fail the privacy sweep the moment
28	 * they crossed into `fixtures/`.
29	 *
30	 * Records are classified by the SAME field the Phase 3 listener uses to route them:
31	 * the presence of `model`. Measured 160/160 Codex against 0/305 Claude Code. The
32	 * classification is cross-checked against the payload's `transcript_path` root, and
33	 * the two signals DISAGREEING is a hard error rather than a tiebreak — a disagreement
34	 * means the assumption moved and a silent pick would bury that.
35	 *
36	 * Filtering is never silent (rule 18): the count and the reason are printed, written
37	 * into the corpus README, and returned to callers.
38	 *
39	 * node: builtins only, so the fixture pipeline never depends on the app's deps.
40	 *
41	 * Usage:
42	 *   node scripts/capture-codex.mjs --from <lab captures dir> --out fixtures/codex-<version>
43	 *                                  [--scratch <abs path>] [--dry-run]
44	 */
45	
46	import fs from 'node:fs';
47	import path from 'node:path';
48	import crypto from 'node:crypto';
49	
50	/** Files under a Codex data root this script must never open. G10. */
51	export const NEVER_OPEN = Object.freeze([
52	  'auth.json',
53	  '.sandbox-secrets',
54	  'installation_id',
55	  'cap_sid',
56	  '*.sqlite',
57	  '*.sqlite-wal',
58	  '*.sqlite-shm',
59	]);
60	
61	const SCRUB_KEY = 'base_instructions';
62	
63	/** Every *.jsonl under a directory, recursively, sorted for determinism. */
64	function jsonlFiles(root) {
65	  const out = [];
66	  const walk = (dir) => {
67	    if (!fs.existsSync(dir)) return;
68	    for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
69	      const p = path.join(dir, e.name);
70	      if (e.isDirectory()) walk(p);
71	      else if (e.name.endsWith('.jsonl')) out.push(p);
72	    }
73	  };
74	  walk(root);
75	  return out;
76	}
77	
78	function readJsonl(file) {
79	  const text = fs.readFileSync(file, 'utf8');
80	  const lines = text.split(/\r?\n/).filter((l) => l.trim());
81	  const records = [];
82	  let malformed = 0;
83	  for (const l of lines) {
84	    try { records.push(JSON.parse(l)); } catch { malformed += 1; }
85	  }
86	  return { records, malformed, lineCount: lines.length };
87	}
88	
89	/**
90	 * Replace the OpenAI system prompt with a digest stub.
91	 *
92	 * Everything else is left byte-exact — ids, call_ids, agent_paths, ordinals,
93	 * timestamps — and the ENCRYPTED reasoning and spawn-message bytes stay verbatim,
94	 * because they are the evidence a G4 test asserts against (see the spec's C7).
95	 */
96	function scrubRecord(rec) {
97	  const bi = rec?.payload?.[SCRUB_KEY];
98	  if (!bi || typeof bi.text !== 'string') return { rec, scrubbed: 0 };
99	  const text = bi.text;
100	  return {
101	    rec: {
102	      ...rec,
103	      payload: {
104	        ...rec.payload,
105	        [SCRUB_KEY]: {
106	          scrubbed: true,
107	          bytes: Buffer.byteLength(text, 'utf8'),
108	          sha256: crypto.createHash('sha256').update(text, 'utf8').digest('hex'),
109	        },
110	      },
111	    },
112	    scrubbed: 1,
113	  };
114	}
115	
116	/** G8: every transcript's cwd must be the scratch repo. Returns offending paths. */
117	function foreignCwds(transcripts, scratch) {
118	  const want = path.resolve(scratch).toLowerCase();
119	  const bad = [];
120	  for (const t of transcripts) {
121	    for (const rec of t.records) {
122	      if (rec?.type !== 'session_meta') continue;
123	      const cwd = rec?.payload?.cwd;
124	      if (typeof cwd !== 'string') continue;
125	      if (path.resolve(cwd).toLowerCase() !== want) bad.push({ file: t.rel, cwd });
126	    }
127	  }
128	  return bad;
129	}
130	
131	/**
132	 * The engine discriminator, and the ONE place its name is written.
133	 *
134	 * Phase 3's listener routes on this same property, so a drift here and a drift there
135	 * are the same defect rather than two. Measured over both corpora: every Codex hook
136	 * payload carries `model` (160/160) and no Claude Code payload does (0/305, including
137	 * 18 live records that arrived on the shared port during these very harvests).
138	 */
139	export const CODEX_HOOK_DISCRIMINATOR = 'model';
140	
141	/** Transcript-path roots, used only to CROSS-CHECK the discriminator. */
142	const CODEX_PATH_MARK = '.codex';
143	const CC_PATH_MARK = '.claude';
144	
145	/**
146	 * Refuse a run whose hook stream is at least this fraction foreign.
147	 *
148	 * Named, not buried in a condition, because the number is a judgement and a later
149	 * reader is entitled to argue with it. A capture that is mostly someone else's
150	 * traffic is not a capture of anything.
151	 */
152	export const FOREIGN_REFUSE_FRACTION = 0.5;
153	
154	/**
155	 * Classify one hook record: 'codex' | 'foreign'.
156	 *
157	 * Throws when the discriminator and the transcript-path root disagree. That is
158	 * deliberate: two independent signals disagreeing is new information, and picking a
159	 * winner would convert it into a silent wrong answer.
160	 */
161	export function classifyHookRecord(record, { run = '?', seq = '?' } = {}) {
162	  const raw = record?.raw ?? record ?? {};
163	  const byField = Object.hasOwn(raw, CODEX_HOOK_DISCRIMINATOR);
164	  const tp = typeof raw.transcript_path === 'string' ? raw.transcript_path : '';
165	  const saysCodex = tp.includes(CODEX_PATH_MARK);
166	  const saysCc = tp.includes(CC_PATH_MARK);
167	
168	  // No usable path signal: fall back to the discriminator alone, which is what the
169	  // listener will have to do too.
170	  if (!saysCodex && !saysCc) return byField ? 'codex' : 'foreign';
171	
172	  if (byField !== saysCodex) {
173	    throw new Error(
174	      `hook classification conflict in run '${run}' seq ${String(seq)}: `
175	      + `'${CODEX_HOOK_DISCRIMINATOR}' key ${byField ? 'present' : 'absent'} but `
176	      + `transcript_path names ${saysCodex ? CODEX_PATH_MARK : CC_PATH_MARK}. `
177	      + 'Two signals disagree; the engine discriminator may have moved. Nothing was written.',
178	    );
179	  }
180	  return byField ? 'codex' : 'foreign';
181	}
182	
183	/**
184	 * Split a hook stream into the Codex records and the foreign ones.
185	 * Refuses when the stream is mostly foreign.
186	 */
187	export function filterHooks(records, { run = '?' } = {}) {
188	  const kept = [];
189	  let dropped = 0;
190	  for (const [i, rec] of records.entries()) {
191	    const seq = rec?.seq ?? i;
192	    if (classifyHookRecord(rec, { run, seq }) === 'codex') kept.push(rec);
193	    else dropped += 1;
194	  }

