1	/**
2	 * Agent Deck — Codex data-root resolution and transcript discovery
3	 * (PLAN.md v0.6.0 Phase 2, DoD 2.1).
4	 *
5	 * Spec C1:
6	 *
7	 *   > The data root is `$CODEX_HOME` when set, otherwise `~/.codex`, resolved
8	 *   > at read time. This is not a convenience: `CODEX_HOME` relocates the
9	 *   > entire surface — sessions, writer locks, `hooks.json` and the credential
10	 *   > file — so an engine that hard-codes the home location observes nothing at
11	 *   > all for such a user.
12	 *
13	 * ---------------------------------------------------------------------------
14	 * THREE PROPERTIES THIS MODULE EXISTS TO HOLD
15	 * ---------------------------------------------------------------------------
16	 *
17	 * **1. Resolved at READ time, from an injected environment.** Nothing here is
18	 * captured at module load. A module-scope `const ROOT = ...` would be resolved
19	 * once per extension-host process, so a user who set the variable after the
20	 * host started, or a test that faked it, would be observed against a stale
21	 * root — and the failure is silence, not an error.
22	 *
23	 * **1a. Three sources, one field that says which.** Precedence is
24	 * **explicit root > `CODEX_HOME` > home**, and {@link CodexDiscovery.rootSource}
25	 * reports which one answered. An explicit root wins because it is an
26	 * instruction from the code that owns the poll rather than a property of the
27	 * machine, and because it is how a caller points at a fixture instead of at a
28	 * live `~/.codex` (G6) — a variable that outranked it would make G6 depend on
29	 * the developer's shell. It is a THIRD value rather than an internal
30	 * translation into `{ CODEX_HOME: root }`: that field's only job is to say
31	 * where the root came from.
32	 *
33	 * **2. The home fallback is PLATFORM-FAITHFUL, and that is a test property.**
34	 * `os.homedir()` reads `USERPROFILE` on Windows and `HOME` on POSIX.
35	 * {@link resolveCodexRoot} consults exactly the one its platform would, so the
36	 * recorded trap stays visible:
37	 *
38	 *   > The negative control needs `USERPROFILE` faked, not just `HOME`. Faking
39	 *   > only `HOME` runs happily against the REAL home and reports a green,
40	 *   > confident, completely false pass.
41	 *
42	 * Reading both would hide it: a test faking only the decoy would pass, and the
43	 * check whose entire purpose is proving we never touch the real home would be
44	 * measuring nothing. `locate.test.ts` asserts the decoy alone does NOT move the
45	 * root, which is the assertion that goes red if this is ever "helpfully"
46	 * widened.
47	 *
48	 * **3. An absent root is a VALUE, not an error.** DoD 2.1: the engine is
49	 * silently off and logs once at info. A machine with no Codex installed must
50	 * not produce a diagnostic every poll — and it must not throw, because the
51	 * poll that throws takes the other two engines' rendering with it (G2).
52	 *
53	 * ---------------------------------------------------------------------------
54	 * THE WALK
55	 * ---------------------------------------------------------------------------
56	 *
57	 * `<root>/sessions/YYYY/MM/DD/rollout-<ISO-ts>-<uuid>.jsonl`. Spec C1: the date
58	 * directories are keyed on the day a thread STARTED, so a session running past
59	 * midnight puts a child under a different day from its parent. **Discovery
60	 * walks the tree; it never reads a single day directory** and never composes
61	 * today's date. `locate.test.ts` plants a transcript under a day that is not
62	 * today and asserts it is found.
63	 *
64	 * The walk carries no idea of what a subagent is, on purpose. Spec C1: a
65	 * subagent's transcript is a SIBLING of its parent's, with nothing in the path
66	 * marking it — so a discovery pass that classifies by path cannot work, and
67	 * {@link CodexTranscriptRef} has nowhere to put such a classification.
68	 *
69	 * G10: every directory entry is tested by name BEFORE it is joined, stat'ed or
70	 * descended into ({@link isNeverOpenName}). The forbidden names are not spelled
71	 * anywhere in this file — see `never-open.ts` for why that is load-bearing
72	 * rather than fastidious.
73	 *
74	 * G1: read-only. `statSync` and `readdirSync` and nothing else. No handle is
75	 * opened here at all; the transcripts are read by `tail.ts`.
76	 * G5: node built-ins only, no sockets.
77	 */
78	
79	import { readdirSync, statSync } from 'node:fs';
80	import { homedir as osHomedir } from 'node:os';
81	import { join } from 'node:path';
82	
83	import type { CodexDiscovery, CodexTranscriptRef } from './types.js';
84	import { isNeverOpenName } from './never-open.js';
85	
86	// ---------------------------------------------------------------------------
87	// Names
88	// ---------------------------------------------------------------------------
89	
90	/** The environment variable that relocates the entire Codex surface (C1). */
91	export const CODEX_HOME_VAR = 'CODEX_HOME';
92	
93	/** The home-relative default, used only when {@link CODEX_HOME_VAR} is unset. */
94	export const CODEX_DEFAULT_DIR_NAME = '.codex';
95	
96	/** `<root>/sessions` — the only content the engine reads. */
97	export const CODEX_SESSIONS_DIR_NAME = 'sessions';
98	
99	/** `<root>/thread-writer-locks` — read by `liveness.ts`, not by this module. */
100	export const CODEX_LOCK_DIR_NAME = 'thread-writer-locks';
101	
102	/**
103	 * `rollout-<ISO-ts>-<uuid>.jsonl`.
104	 *
105	 * Deliberately loose about the middle: the timestamp spelling and the uuid
106	 * version are Codex's business, and a pattern that pinned them would turn a
107	 * cosmetic change in a filename into a machine with no sessions. The parts that
108	 * matter are the prefix (which distinguishes a transcript from anything else
109	 * Codex may one day put in a day directory) and the extension.
110	 */
111	export const CODEX_ROLLOUT_FILE_RE = /^rollout-.+\.jsonl$/i;
112	
113	/**
114	 * How deep below `<root>/sessions` the observed corpus puts a transcript:
115	 * `YYYY`, `MM`, `DD`.
116	 *
117	 * Documentation and a test anchor, **not** a rule the walk enforces. A
118	 * transcript found shallower or deeper is still reported, with `day` carrying
119	 * the segments actually walked. Pinning the depth would turn a Codex that
120	 * regroups its sessions into a machine with none.
121	 */
122	export const CODEX_DAY_DEPTH = 3;
123	
124	/**
125	 * Hard stop on recursion below `sessions/`, whatever the tree holds. Not a
126	 * schema either — it is the thing that stops a symlink loop or a pathological
127	 * tree from spinning a poll forever.
128	 */
129	const MAX_WALK_DEPTH = 8;
130	
131	// ---------------------------------------------------------------------------
132	// The fs seam
133	// ---------------------------------------------------------------------------
134	
135	/** Only what this module reads. Structurally satisfied by `fs.Stats`. */
136	export interface CodexLocateStats {
137	  isFile(): boolean;
138	  isDirectory(): boolean;
139	  size: number;
140	  mtimeMs: number;
141	}
142	
143	/** Structurally satisfied by `fs.Dirent`. */
144	export interface CodexLocateDirent {
145	  name: string;
146	  isDirectory(): boolean;
147	  isFile(): boolean;
148	}
149	
150	/**
151	 * Synchronous, like `src/watch/inference.ts`'s seam and for the same reason:
152	 * discovery is called on a poll and returns a value, not a promise. Both
153	 * members may throw; every call site here catches.
154	 *
155	 * It is a seam rather than a convenience. A test can record every path this
156	 * module hands to the filesystem and assert the G10 list never appears among
157	 * them — which is an enforcement of "never opened", not a proxy for it.
158	 */
159	export interface CodexLocateFs {
160	  statSync(path: string): CodexLocateStats;
161	  readdirSync(path: string): CodexLocateDirent[];
162	}
163	
164	const nodeLocateFs: CodexLocateFs = {
165	  statSync: (path) => statSync(path),
166	  readdirSync: (path) => readdirSync(path, { withFileTypes: true }),
167	};
168	
169	// ---------------------------------------------------------------------------
170	// Logging
171	// ---------------------------------------------------------------------------
172	
173	/**
174	 * The one thing DoD 2.1 asks to be logged, and the levels it may be logged at.
175	 *
176	 * `info`, not `warn`: a machine without Codex is the normal case, not a
177	 * degradation. The reason travels beside the level so a reader of the log
178	 * never has to infer why the engine went quiet — rule 18's "a check that skips
179	 * an input must say so", applied to an engine that skips a whole machine.
180	 */
181	export interface CodexLocateLogRecord {
182	  readonly level: 'info';
183	  readonly event: 'rootAbsent';
184	  readonly root: string;
185	  readonly rootSource: CodexDiscovery['rootSource'];
186	  readonly message: string;
187	}
188	
189	export type CodexLocateLogger = (record: CodexLocateLogRecord) => void;
190	
191	// ---------------------------------------------------------------------------
192	// Root resolution
193	// ---------------------------------------------------------------------------
194	
195	export interface CodexRootOptions {
196	  /**
197	   * The data root, named outright by the caller
198	   * ({@link CodexEngineOptions.root} in `types.ts`).
199	   *
200	   * **Precedence: explicit root > `CODEX_HOME` > home.** An explicit root is an
201	   * instruction from the code that owns the poll, and it is how a caller points
202	   * at a fixture instead of at a live `~/.codex` (G6); an environment variable
203	   * that outranked it would make G6 depend on the developer's shell.
204	   *
205	   * It is reported as its own {@link CodexDiscovery.rootSource} value and is
206	   * NOT implemented by synthesising `{ CODEX_HOME: root }` internally. That
207	   * field's only job is to say where the root came from, so answering
208	   * `'CODEX_HOME'` when no environment variable was involved would be a wrong
209	   * answer in the one field that exists to give the right one.
210	   */
211	  readonly root?: string;
212	
213	  /** The environment to resolve against. Defaults to `process.env`. */
214	  readonly env?: NodeJS.ProcessEnv;
215	}
216	
217	export interface CodexResolvedRoot {
218	  readonly root: string;
219	  readonly rootSource: CodexDiscovery['rootSource'];
220	}
221	
222	/**
223	 * The home directory, read from `env` the way `os.homedir()` reads
224	 * `process.env` — one variable, chosen by platform. See property 2 in the file
225	 * header for why consulting both would destroy a test rather than improve it.
226	 */
227	function homeFromEnv(env: NodeJS.ProcessEnv): string {
228	  const name = process.platform === 'win32' ? 'USERPROFILE' : 'HOME';
229	  const value = env[name];
230	  if (typeof value === 'string' && value.trim() !== '') return value;
231	  // `env` said nothing. Fall back to node's own answer, which on a real
232	  // process is the same variable plus a syscall.
233	  return osHomedir();
234	}
235	
236	/**
237	 * An explicit root when the caller named one, else `$CODEX_HOME` when set and
238	 * non-empty, else `<home>/.codex`. Resolved on every call; nothing is memoised
239	 * (property 1).
240	 *
241	 * **An empty or whitespace-only value is treated as unset, for BOTH the option
242	 * and the variable.** A variable set to the empty string is how a shell spells
243	 * "I cleared this", and honouring either literally would resolve the root to
244	 * `sessions` relative to the process cwd — a wrong answer that reads as a Codex
245	 * with no sessions rather than as the caller error it is. One rule for both, so
246	 * there is nothing to remember about which is which.
247	 */
248	export function resolveCodexRoot(options: CodexRootOptions = {}): CodexResolvedRoot {
249	  const explicit = options.root;
250	  if (typeof explicit === 'string' && explicit.trim() !== '') {
251	    return { root: explicit, rootSource: 'explicit' };
252	  }
253	  const env = options.env ?? process.env;
254	  const fromVar = env[CODEX_HOME_VAR];
255	  if (typeof fromVar === 'string' && fromVar.trim() !== '') {
256	    return { root: fromVar, rootSource: 'CODEX_HOME' };
257	  }
258	  return { root: join(homeFromEnv(env), CODEX_DEFAULT_DIR_NAME), rootSource: 'homedir' };
259	}
260	
261	// ---------------------------------------------------------------------------
262	// Discovery
263	// ---------------------------------------------------------------------------
264	
265	export interface CodexLocateOptions extends CodexRootOptions {
266	  /** Injection seam for tests. Defaults to `node:fs`. */
267	  readonly fs?: CodexLocateFs;
268	}
269	
270	/**
271	 * One discovery pass. Never throws (G3): an unreadable root, an unreadable day
272	 * directory and a vanished file are all absorbed, and the result is whatever
273	 * was legibly there.
274	 *
275	 * `rootExists: false` with an empty `transcripts` is the normal state on a
276	 * machine with no Codex. It is NOT distinguished here from a root that exists
277	 * but holds no `sessions` directory — that one reports `rootExists: true` with
278	 * no transcripts, which is a different fact and is the one a user who has
279	 * installed Codex but never run it will see.
280	 */
281	export function locateCodex(options: CodexLocateOptions = {}): CodexDiscovery {
282	  const fs = options.fs ?? nodeLocateFs;
283	  const { root, rootSource } = resolveCodexRoot(options);
284	  const lockDir = join(root, CODEX_LOCK_DIR_NAME);
285	
286	  if (!isDirectory(fs, root)) {
287	    return { root, rootSource, rootExists: false, transcripts: [], lockDir };
288	  }
289	
290	  const sessionsDir = join(root, CODEX_SESSIONS_DIR_NAME);
291	  const transcripts: CodexTranscriptRef[] = [];
292	  if (isDirectory(fs, sessionsDir)) {
293	    walk(fs, sessionsDir, [], transcripts, 0);
294	  }
295	
296	  // Stable across polls and across platforms: `readdirSync` order is the
297	  // filesystem's, and a caller diffing two discoveries must not see a reorder
298	  // reported as a change.
299	  transcripts.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
300	
301	  return { root, rootSource, rootExists: true, transcripts, lockDir };
302	}
303	
304	function isDirectory(fs: CodexLocateFs, path: string): boolean {
305	  try {
306	    return fs.statSync(path).isDirectory();
307	  } catch {
308	    return false;
309	  }
310	}
311	
312	/**
313	 * Depth-first walk below `sessions/`, accumulating rollout files.
314	 *
315	 * `relative` is the segments walked so far, so `day` is reported as the tree
316	 * spelled it rather than as a date this module composed. That distinction is
317	 * the whole of "it never reads a single day directory": there is no place here
318	 * where a `YYYY/MM/DD` could be built from a clock.
319	 */
320	function walk(
321	  fs: CodexLocateFs,
322	  dir: string,
323	  relative: readonly string[],
324	  out: CodexTranscriptRef[],
325	  depth: number,
326	): void {
327	  if (depth > MAX_WALK_DEPTH) return;
328	
329	  let entries: CodexLocateDirent[];
330	  try {
331	    entries = fs.readdirSync(dir);
332	  } catch {
333	    return; // G3: an unreadable directory is empty, not fatal.
334	  }
335	
336	  for (const entry of entries) {
337	    // G10, and the order matters: the name is judged BEFORE anything is
338	    // joined, stat'ed or descended into. There is no point at which a
339	    // forbidden path exists as a string that has been handed to the
340	    // filesystem.
341	    if (isNeverOpenName(entry.name)) continue;
342	
343	    const full = join(dir, entry.name);
344	
345	    if (entry.isDirectory()) {
346	      walk(fs, full, [...relative, entry.name], out, depth + 1);
347	      continue;
348	    }
349	    if (!entry.isFile()) continue;
350	    if (!CODEX_ROLLOUT_FILE_RE.test(entry.name)) continue;
351	
352	    let stats: CodexLocateStats;
353	    try {
354	      stats = fs.statSync(full);
355	    } catch {
356	      continue; // vanished between readdir and stat: it is simply not there.
357	    }
358	    if (!stats.isFile()) continue;
359	
360	    out.push({
361	      path: full,
362	      file: entry.name,
363	      day: relative.join('/'),
364	      bytes: stats.size,
365	      mtimeMs: stats.mtimeMs,
366	    });
367	  }
368	}
369	
370	// ---------------------------------------------------------------------------
371	// The once-latch
372	// ---------------------------------------------------------------------------
373	
374	export interface CodexLocatorOptions extends CodexLocateOptions {
375	  /**
376	   * Where the one absent-root line goes. Omitted means nothing is logged at
377	   * all, which is the right default for a library: this module must not reach
378	   * for a global console, because a host that wants the line in its own output
379	   * channel would then get it twice and a test could not count it.
380	   */
381	  readonly log?: CodexLocateLogger;
382	}
383	
384	/**
385	 * A locator that carries the "logged once" of DoD 2.1 across polls.
386	 *
387	 * {@link locateCodex} is a pure function of the environment and the filesystem
388	 * and has no memory, which is what makes it testable. The latch has to live
389	 * somewhere, so it lives here rather than in a module-scope boolean — a global
390	 * would be shared between the extension host's engines and between a test file's
391	 * cases, and "exactly once" is not assertable against shared state.
392	 *
393	 * **The latch is per resolved root, and it CLEARS when the root appears.** A
394	 * user who installs Codex mid-session, then uninstalls it, gets one line each
395	 * time it goes away rather than one line ever: the second disappearance is new
396	 * information. The alternative — latch forever — is silence about a state
397	 * change, which is the fail-open reading rule 18 exists to refuse.
398	 */
399	export class CodexLocator {
400	  readonly #options: CodexLocatorOptions;
401	  #loggedAbsentRoot: string | null = null;
402	
403	  constructor(options: CodexLocatorOptions = {}) {
404	    this.#options = options;
405	  }
406	
407	  /** Runs one discovery pass and logs the absent root at most once per absence. */
408	  locate(): CodexDiscovery {
409	    const discovery = locateCodex(this.#options);
410	
411	    if (discovery.rootExists) {
412	      this.#loggedAbsentRoot = null;
413	      return discovery;
414	    }
415	
416	    if (this.#loggedAbsentRoot !== discovery.root) {
417	      this.#loggedAbsentRoot = discovery.root;
418	      this.#options.log?.({
419	        level: 'info',
420	        event: 'rootAbsent',
421	        root: discovery.root,
422	        rootSource: discovery.rootSource,
423	        message:
424	          `no Codex data root at ${discovery.root} ` +
425	          `(from ${discovery.rootSource}); the Codex engine is off`,
426	      });
427	    }
428	
429	    return discovery;
430	  }
431	
432	  /** Whether the absent-root line has been emitted for the current absence. */
433	  get hasLoggedAbsentRoot(): boolean {
434	    return this.#loggedAbsentRoot !== null;
435	  }
436	}
437

