1	/**
2	 * Agent Deck — the Codex engine's liveness tap (`PLAN.md` v0.6.0 DoD 2.5,
3	 * spec C6, Phase 0 decision D0.1).
4	 *
5	 * Answers "what is running right now" for Codex threads from three sources, in
6	 * this order of authority:
7	 *
8	 *   1. the loopback hook tap        — PRIMARY
9	 *   2. `<root>/thread-writer-locks` — fallback, and D0.1's other conjunct
10	 *   3. the transcript's mtime       — corroboration only
11	 *
12	 * ---------------------------------------------------------------------------
13	 * D0.1 IS AN `AND`, AND EVERY WORD OF IT IS LOAD-BEARING
14	 * ---------------------------------------------------------------------------
15	 *
16	 *   > An agent is dead when its writer lock is gone AND no hook event has
17	 *   > arrived within `livenessThresholdMs`. `SubagentStop` only clears
18	 *   > "in flight"; it never marks dead.
19	 *
20	 * Two measured facts force that shape, and there is a test for each:
21	 *
22	 *  - **`SubagentStop` fires per TURN, not once per agent.**
23	 *    `docs/codex-contract.md` A2: `resume-twice-v1` shows **1 start against 2
24	 *    stops for one agent**, on **2 distinct `turn_id`s** — the agent stopped,
25	 *    was resumed to report on a child, and stopped again. An engine that marks
26	 *    an agent dead on `SubagentStop` kills a live agent. This is the recorded
27	 *    Claude Code finding that `stop_reason: "end_turn"` looks like a
28	 *    terminator and is one per turn, arriving on the other tap.
29	 *  - **`SubagentStart` may never arrive.** Phase 0 saw a subagent produce a
30	 *    `SubagentStop` and a full transcript with no start. A2 re-measured that on
31	 *    a clean tap and it did NOT reproduce (9 of 9 agents that stopped also
32	 *    started) — which **retires the observation, not the rule**. Nothing here
33	 *    requires the event, and a test proves a stop-only stream still resolves.
34	 *
35	 * `SubagentStop` therefore clears {@link CodexLiveness.inFlight} and touches
36	 * {@link CodexLiveness.state} not at all. Same for `Stop` and `SessionEnd`.
37	 *
38	 * ---------------------------------------------------------------------------
39	 * THE STATE TABLE, WHICH IS THE WHOLE MODULE
40	 * ---------------------------------------------------------------------------
41	 *
42	 * ```
43	 * hookRecent   last hook event for this thread within livenessThresholdMs
44	 * hookSeen     any hook event for this thread, at any age
45	 * lockKnown    the writer-lock directory was there and was read
46	 * lockPresent  lockKnown and <threadId>.lock was among its entries
47	 * mtimeRecent  the owning transcript was written within livenessThresholdMs
48	 *
49	 * 1  hookRecent            -> live     degraded: none
50	 * 2  !lockKnown            -> idle if mtimeRecent else unknown
51	 *                                      degraded: mtimeOnly | lockDirMissing
52	 * 3  lockPresent           -> idle     degraded: noHookEvents if !hookSeen
53	 * 4  otherwise (lock gone) -> DEAD     degraded: noHookEvents if !hookSeen
54	 * ```
55	 *
56	 * Row 4 is D0.1 and it is reached only when **both** conjuncts hold: the lock
57	 * is gone (row 2 has already taken the case where we could not tell) and no
58	 * hook event arrived inside the window (row 1 has already taken the other).
59	 *
60	 * **`mtimeRecent` is deliberately NOT a third disjunct against death.** Spec
61	 * C6 says a lock is "evidence of life, not proof — it is corroborated by
62	 * transcript mtime": corroboration confirms life, it does not create it.
63	 * Making a recent write veto row 4 would (a) add a term D0.1 does not have,
64	 * (b) make a hookless, lockless thread with one recent write immortal, and
65	 * (c) weaken the `AND`-to-`OR` mutation this module's tests exist to catch.
66	 * mtime decides only where D0.1 cannot be evaluated at all (row 2).
67	 *
68	 * ---------------------------------------------------------------------------
69	 * A DEGRADED STATE THAT DOES NOT SAY IT IS DEGRADED IS THE SILENT-SKIP CLASS
70	 * ---------------------------------------------------------------------------
71	 * Working-method rule 18. Every row above that did not decide on the primary
72	 * tap carries a {@link CodexLivenessDegradation}, and the three codes are
73	 * assigned in a fixed priority so one value can name the most specific thing
74	 * that was unavailable:
75	 *
76	 *   `mtimeOnly`      no hook events AND no lock information, but an mtime; the
77	 *                    transcript's mtime was the only evidence there was.
78	 *   `lockDirMissing` the writer-lock directory was absent or unreadable, so
79	 *                    D0.1's lock conjunct could not be evaluated.
80	 *   `noHookEvents`   the primary tap said nothing about this thread; the lock
81	 *                    scan decided the state.
82	 *
83	 * The lock scan reports its own skips the same way
84	 * ({@link CodexLockScan.skipped}): a name it declined to read as a thread id
85	 * travels with the reason it declined.
86	 *
87	 * ---------------------------------------------------------------------------
88	 * `.coordination.lock` IS NOT A THREAD
89	 * ---------------------------------------------------------------------------
90	 * Spec C1 lists it beside the thread locks and says so outright; the contract
91	 * measures it present at process exit on 6 of 6 runs while every thread lock
92	 * was gone. A scan that reads it as a thread id invents a live agent named
93	 * `.coordination` that never existed — and it would be live forever, because
94	 * that file outlives every thread.
95	 *
96	 * ---------------------------------------------------------------------------
97	 * ABSENCE OF `agent_id` IS THE SIGNAL (spec C11)
98	 * ---------------------------------------------------------------------------
99	 * Every Codex hook event carries the ROOT thread's `session_id`, even for a
100	 * subagent's own tool calls, and a main-thread event **omits `agent_id`
101	 * entirely** rather than sending a sentinel. A correlator matching a literal
102	 * `"main"` drops every root event — the rule this repository already shipped
103	 * wrong once, on Claude Code. So: `agent_id` present names the thread;
104	 * `agent_id` absent means the event belongs to the root thread, whose id is
105	 * `session_id`. Measured over the committed corpus's 110 records: **53 carry
106	 * `agent_id`, 57 do not**, and the literal string `"main"` occurs zero times.
107	 * The test re-derives all three from the corpus rather than reading them here.
108	 *
109	 * ---------------------------------------------------------------------------
110	 * THE JOIN IS OVER THE UNION OF TWO ID NAMESPACES (spec C4)
111	 * ---------------------------------------------------------------------------
112	 * A hook payload's `tool_use_id` resolves against
113	 * `response_item.payload.call_id` (always `call_…`) **or**
114	 * `event_msg.payload.item.id` (`exec-<uuid>` for a shell command), and the tap
115	 * reports the ITEM id. An engine joining on `call_id` alone silently drops
116	 * every shell call. {@link joinCodexHookToolIds} indexes both and reports the
117	 * three counts so a caller can see the gap rather than infer it; the test
118	 * derives them from the corpus and asserts the relation rather than pinning
119	 * numbers from a document.
120	 *
121	 * `ToolNode.id` cannot carry the second id — it has one id field — so this
122	 * join is done here, against {@link CodexToolCall}, and never through the tree.
123	 *
124	 * ---------------------------------------------------------------------------
125	 * NO CLOCK AND NO TIMER LIVE IN THIS FILE
126	 * ---------------------------------------------------------------------------
127	 * `now` and the poll trigger are injected, exactly as `src/opencode/
128	 * liveness.ts` injects them and for the same recorded reason: a threshold test
129	 * that sleeps measures the machine it ran on and fails under load. There is no
130	 * `Date.now()`, no `setInterval` and no `setTimeout` below this comment.
131	 * {@link CodexLivenessDeps} in `types.ts` is the injection point for the first
132	 * two; {@link CodexPollTrigger} is the third, and it is declared here because
133	 * the hand-off line does not declare it and no work package may edit that file.
134	 *
135	 * G1: this module never writes. It reads directory ENTRIES from the lock
136	 * directory and never opens a lock file — the files are 0 bytes and their name
137	 * is the whole payload. G5: no sockets; hook events arrive from the loopback
138	 * listener the host already owns.
139	 */
140	
141	import { readdirSync, statSync } from 'node:fs';
142	import { join } from 'node:path';
143	
144	import type {
145	  CodexLiveness,
146	  CodexLivenessDegradation,
147	  CodexLivenessDeps,
148	  CodexToolCall,
149	} from './types.js';
150	
151	// ---------------------------------------------------------------------------
152	// Constants
153	// ---------------------------------------------------------------------------
154	
155	/** Suffix of a writer-lock file. The stem is the thread id, exactly (§7). */
156	export const CODEX_LOCK_SUFFIX = '.lock';
157	
158	/**
159	 * The one entry in the writer-lock directory that is NOT a thread.
160	 *
161	 * Named as a constant rather than filtered by a leading-dot rule alone,
162	 * because the two checks fail differently: the constant is what the spec
163	 * writes down, and the dot rule is what catches a sibling nobody has met yet.
164	 * Both run, and each records its own skip reason.
165	 */
166	export const CODEX_COORDINATION_LOCK_NAME = '.coordination.lock';
167	
168	/**
169	 * Matches `src/model/liveness.ts`'s 120 s mtime threshold and
170	 * {@link DEFAULT_OC_LIVENESS_THRESHOLD_MS}'s value in the OpenCode engine. A
171	 * default, never a policy: {@link CodexLivenessDeps.livenessThresholdMs} is
172	 * required, so nothing reaches the rule without a caller having chosen.
173	 */
174	export const DEFAULT_CODEX_LIVENESS_THRESHOLD_MS = 120_000;
175	
176	/** Default cadence for {@link CodexLivenessEngine}, when a trigger is given. */
177	export const DEFAULT_CODEX_POLL_INTERVAL_MS = 1000;
178	
179	/**
180	 * Hook events that clear "in flight" and mark NOTHING dead.
181	 *
182	 * All three are per-TURN terminators, not per-agent ones. `SubagentStop` is
183	 * the measured case (2 stops, 1 agent, 2 turn ids); `Stop` is its main-thread
184	 * twin and the corpus shows one per run at the end of a turn; `SessionEnd` is
185	 * registered in `hooks.json` and did not fire in the committed streams, so it
186	 * is handled by the same rule rather than by a guess about what it means.
187	 */
188	export const CODEX_IN_FLIGHT_CLEARING_EVENTS: ReadonlySet<string> = new Set([
189	  'SubagentStop',
190	  'Stop',
191	  'SessionEnd',
192	]);
193	
194	// ---------------------------------------------------------------------------
195	// The hook tap's input
196	// ---------------------------------------------------------------------------
197	
198	/**
199	 * One hook event as this module consumes it: **the engine's own payload, plus
200	 * the arrival time the listener stamped on it.**
201	 *
202	 * The split is deliberate and it is the trap this file was warned about. A
203	 * captured stream nests two layers — the listener's envelope
204	 * (`seq`, `receivedAt`, `eventName`, `sessionId`, `agentId`, `isMainThread`,
205	 * `toolUseId`, `raw`) around the engine's payload (`raw`). Every identity fact
206	 * belongs to the payload and every derived convenience field on the envelope is
207	 * the CAPTURE's opinion of it. Reading identity off the envelope gets the right
208	 * answer on this corpus — the two agree on 110 of 110 records, measured — and
209	 * gets it by trusting a script instead of the engine.
210	 *
211	 * The time is the exception, and it is an exception on the merits: Codex hook
212	 * payloads carry **no timestamp of any kind** (census over the corpus: 18
213	 * distinct payload keys, none of them a time), so arrival time is a genuine
214	 * property of the envelope. "No hook event has ARRIVED within the threshold"
215	 * is a statement about receipt, which is what the listener stamps.
216	 */
217	export interface CodexHookEvent {
218	  /** When the loopback listener received the POST, epoch ms. */
219	  readonly receivedAtMs: number;
220	  /** The engine's hook payload, verbatim. Never trusted to be an object. */
221	  readonly payload: unknown;
222	}
223	
224	/** Why {@link readCodexHookStream} did not turn a line into an event. */
225	export interface CodexHookSkip {
226	  readonly line: number;
227	  readonly reason: 'malformedJson' | 'notAnObject' | 'noPayload' | 'noReceivedAt';
228	}
229	
230	export interface CodexHookRead {
231	  readonly events: readonly CodexHookEvent[];
232	  /** Lines that did not parse as JSON. Counted and skipped, never thrown (G3). */
233	  readonly malformedLines: number;
234	  /**
235	   * Records whose envelope contradicted its own payload on `session_id`,
236	   * `agent_id` or `tool_use_id`.
237	   *
238	   * Zero on the committed corpus, and the count exists because "they agree"
239	   * is only worth anything if disagreement is visible. `capture-codex.mjs`
240	   * treats a disagreement between two signals as a hard error rather than a
241	   * tiebreak, for the recorded reason: a disagreement means an assumption
242	   * moved, and picking a winner buries that. A READER may not throw (G3), so
243	   * it counts, and the payload always wins.
244	   */
245	  readonly envelopeDisagreements: number;
246	  readonly skipped: readonly CodexHookSkip[];
247	}
248	
249	/**
250	 * Read a captured or replayed listener stream into {@link CodexHookEvent}s.
251	 *
252	 * One JSON object per line, the listener's envelope form. Never throws: a
253	 * malformed line is counted and skipped, which is G3 applied to the tap that
254	 * G2 says must not be able to take content parsing down with it.
255	 */
256	export function readCodexHookStream(text: string): CodexHookRead {
257	  const events: CodexHookEvent[] = [];
258	  const skipped: CodexHookSkip[] = [];
259	  let malformedLines = 0;
260	  let envelopeDisagreements = 0;
261	
262	  const lines = text.split('\n');
263	  for (let i = 0; i < lines.length; i += 1) {
264	    const raw = lines[i];
265	    if (raw === undefined) continue;
266	    const trimmed = raw.replace(/\r$/, '').trim();
267	    if (trimmed === '') continue;
268	
269	    let parsed: unknown;
270	    try {
271	      parsed = JSON.parse(trimmed);
272	    } catch {
273	      malformedLines += 1;
274	      skipped.push({ line: i + 1, reason: 'malformedJson' });
275	      continue;
276	    }
277	
278	    const envelope = asObject(parsed);
279	    if (envelope === null) {
280	      skipped.push({ line: i + 1, reason: 'notAnObject' });
281	      continue;
282	    }
283	    const payload = asObject(envelope['raw']);
284	    if (payload === null) {
285	      skipped.push({ line: i + 1, reason: 'noPayload' });
286	      continue;
287	    }
288	    const receivedAtMs = envelope['receivedAt'];
289	    if (typeof receivedAtMs !== 'number' || !Number.isFinite(receivedAtMs)) {
290	      skipped.push({ line: i + 1, reason: 'noReceivedAt' });
291	      continue;
292	    }
293	
294	    if (
295	      disagrees(envelope['sessionId'], payload['session_id']) ||
296	      disagrees(envelope['agentId'], payload['agent_id']) ||
297	      disagrees(envelope['toolUseId'], payload['tool_use_id'])
298	    ) {
299	      envelopeDisagreements += 1;
300	    }
301	
302	    events.push({ receivedAtMs, payload });
303	  }
304	
305	  return { events, malformedLines, envelopeDisagreements, skipped };
306	}
307	
308	/** `undefined` and an absent key are the same claim here; anything else must match. */
309	function disagrees(envelopeValue: unknown, payloadValue: unknown): boolean {
310	  const a = envelopeValue === undefined ? null : envelopeValue;
311	  const b = payloadValue === undefined ? null : payloadValue;
312	  return a !== b;
313	}
314	
315	function asObject(value: unknown): Record<string, unknown> | null {
316	  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
317	  return value as Record<string, unknown>;
318	}
319	
320	function nonEmptyString(value: unknown): string | null {
321	  return typeof value === 'string' && value !== '' ? value : null;
322	}
323	
324	// ---------------------------------------------------------------------------
325	// The writer-lock scan
326	// ---------------------------------------------------------------------------
327	
328	/** A directory entry the scan declined to read as a thread lock, and why. */
329	export interface CodexLockScanSkip {
330	  readonly name: string;
331	  readonly reason: 'coordinationLock' | 'dotFile' | 'notALockFile' | 'notAFile';
332	}
333	
334	export interface CodexLockScan {
335	  readonly dir: string;
336	  /** The directory was there and was read. `false` degrades, never refuses. */
337	  readonly exists: boolean;
338	  /** One id per `<thread-uuid>.lock`, in directory order. */
339	  readonly threadIds: readonly string[];
340	  /** Rule 18: every entry NOT counted is named with its reason. */
341	  readonly skipped: readonly CodexLockScanSkip[];
342	  /** The readdir failure, if any. Recorded rather than thrown. */
343	  readonly error: string | null;
344	}
345	
346	/**
347	 * A directory entry, as narrow as this scan needs. Structurally satisfied by
348	 * `fs.Dirent`, and the same seam shape `locate.ts` uses — injected so a test
349	 * can assert what was handed to the filesystem, which is an enforcement of
350	 * "the lock FILES are never opened" rather than a proxy for it.
351	 */
352	export interface CodexLockDirent {
353	  name: string;
354	  isFile(): boolean;
355	}
356	
357	export interface CodexLockFs {
358	  readdirSync(path: string): CodexLockDirent[];
359	}
360	
361	const nodeLockFs: CodexLockFs = {
362	  readdirSync: (path) => readdirSync(path, { withFileTypes: true }),
363	};
364	
365	/**
366	 * List the live threads according to `<root>/thread-writer-locks`.
367	 *
368	 * The contract's §7 measurement is what this rests on: a lock file's name IS a
369	 * thread id (14 of 14 named for a `session_meta.id`), it appears near thread
370	 * start and is removed at thread end (14 of 14 gone at process exit), and
371	 * Codex clears stale locks from previous runs at startup. What it does NOT
372	 * establish is whether a lock survives a hard kill — hence "evidence of life,
373	 * not proof", and hence D0.1 needing the hook conjunct as well.
374	 *
375	 * Never throws. A missing directory is `exists: false`, which degrades
376	 * liveness with {@link CodexLivenessDegradation} rather than refusing anything.
377	 */
378	export function scanCodexWriterLocks(dir: string, fs: CodexLockFs = nodeLockFs): CodexLockScan {
379	  let entries: CodexLockDirent[];
380	  try {
381	    entries = fs.readdirSync(dir);
382	  } catch (error) {
383	    return {
384	      dir,
385	      exists: false,
386	      threadIds: [],
387	      skipped: [],
388	      error: error instanceof Error ? error.message : String(error),
389	    };
390	  }
391	
392	  const threadIds: string[] = [];
393	  const skipped: CodexLockScanSkip[] = [];
394	  for (const entry of entries) {
395	    const name = entry.name;
396	    if (name === CODEX_COORDINATION_LOCK_NAME) {
397	      skipped.push({ name, reason: 'coordinationLock' });
398	      continue;
399	    }
400	    if (name.startsWith('.')) {
401	      skipped.push({ name, reason: 'dotFile' });
402	      continue;
403	    }
404	    if (!name.endsWith(CODEX_LOCK_SUFFIX) || name.length === CODEX_LOCK_SUFFIX.length) {
405	      skipped.push({ name, reason: 'notALockFile' });
406	      continue;
407	    }
408	    if (!entry.isFile()) {
409	      skipped.push({ name, reason: 'notAFile' });
410	      continue;
411	    }
412	    threadIds.push(name.slice(0, name.length - CODEX_LOCK_SUFFIX.length));
413	  }
414	
415	  return { dir, exists: true, threadIds, skipped, error: null };
416	}
417	
418	/** `<root>/thread-writer-locks` for a discovery's `lockDir`, scanned. */
419	export function scanCodexWriterLocksIn(root: string, lockDirName: string): CodexLockScan {
420	  return scanCodexWriterLocks(join(root, lockDirName));
421	}
422	
423	/**
424	 * `statSync().mtimeMs` for a transcript, or `null` if it cannot be read.
425	 *
426	 * The mtime is an END — the file's last write — and is corroboration only. It
427	 * is never a start: `CodexThread.startedAtMs` exists in `types.ts` precisely
428	 * because the grafter was once about to default a start to this number.
429	 */
430	export function readTranscriptMtimeMs(path: string): number | null {
431	  try {
432	    return statSync(path).mtimeMs;
433	  } catch {
434	    return null;
435	  }
436	}
437	
438	// ---------------------------------------------------------------------------
439	// The hook join (spec C4)
440	// ---------------------------------------------------------------------------
441	
442	/**
443	 * Both id namespaces a hook `tool_use_id` may land in, for one tool call:
444	 * `callId` always, `itemId` when the call had an `event_msg` item.
445	 */
446	export function codexHookJoinKeys(call: CodexToolCall): readonly string[] {
447	  const keys = [call.callId];
448	  if (call.itemId !== null && call.itemId !== call.callId) keys.push(call.itemId);
449	  return keys;
450	}
451	
452	/** Index every tool call under BOTH of its ids. The union, never one of them. */
453	export function buildCodexToolCallIndex(
454	  calls: readonly CodexToolCall[],
455	): ReadonlyMap<string, CodexToolCall> {
456	  const index = new Map<string, CodexToolCall>();
457	  for (const call of calls) {
458	    for (const key of codexHookJoinKeys(call)) {
459	      if (key !== '') index.set(key, call);
460	    }
461	  }
462	  return index;
463	}
464	
465	/**
466	 * How a corpus of hook events resolves against a corpus of tool calls, counted
467	 * three ways so the gap between them is visible rather than inferred.
468	 *
469	 * `resolvedUnion` is what the engine does. `resolvedByCallId` is what an engine
470	 * that reached for the obvious field would do, and the difference between the
471	 * two is the shell calls it would have dropped.
472	 */
473	export interface CodexHookJoinCounters {
474	  /** Hook records carrying a `tool_use_id` at all. */
475	  readonly hookIdsSeen: number;
476	  readonly resolvedUnion: number;
477	  readonly resolvedByCallId: number;
478	  readonly resolvedByItemId: number;
479	  readonly unresolved: number;
480	}
481	
482	export function joinCodexHookToolIds(
483	  events: readonly CodexHookEvent[],
484	  calls: readonly CodexToolCall[],
485	): CodexHookJoinCounters {
486	  const byCallId = new Set<string>();
487	  const byItemId = new Set<string>();
488	  for (const call of calls) {
489	    if (call.callId !== '') byCallId.add(call.callId);
490	    if (call.itemId !== null && call.itemId !== '') byItemId.add(call.itemId);
491	  }
492	
493	  let hookIdsSeen = 0;
494	  let resolvedUnion = 0;
495	  let resolvedByCallId = 0;
496	  let resolvedByItemId = 0;
497	  for (const event of events) {
498	    const payload = asObject(event.payload);
499	    if (payload === null) continue;
500	    const id = nonEmptyString(payload['tool_use_id']);
501	    if (id === null) continue;
502	    hookIdsSeen += 1;
503	    const inCall = byCallId.has(id);
504	    const inItem = byItemId.has(id);
505	    if (inCall) resolvedByCallId += 1;
506	    if (inItem) resolvedByItemId += 1;
507	    if (inCall || inItem) resolvedUnion += 1;
508	  }
509	
510	  return {
511	    hookIdsSeen,
512	    resolvedUnion,
513	    resolvedByCallId,
514	    resolvedByItemId,
515	    unresolved: hookIdsSeen - resolvedUnion,
516	  };
517	}
518	
519	// ---------------------------------------------------------------------------
520	// The hook reduction
521	// ---------------------------------------------------------------------------
522	
523	/**
524	 * What the tap knows about one thread, reduced from its events.
525	 *
526	 * Held as a reduction rather than as a retained event list so
527	 * {@link CodexLivenessEngine} can apply one event at a time and keep nothing
528	 * that grows with session length.
529	 */
530	export interface CodexThreadHookState {
531	  readonly threadId: string;
532	  /** Whether the thread was named by `agent_id` or inferred as the root (C11). */
533	  readonly attributedBy: 'agent_id' | 'session_id';
534	  readonly lastEventMs: number | null;
535	  readonly openToolUseIds: ReadonlySet<string>;
536	  readonly subagentStarts: number;
537	  readonly subagentStops: number;
538	  readonly events: number;
539	}
540	
541	interface MutableHookState {
542	  threadId: string;
543	  attributedBy: 'agent_id' | 'session_id';
544	  lastEventMs: number | null;
545	  openToolUseIds: Set<string>;
546	  subagentStarts: number;
547	  subagentStops: number;
548	  events: number;
549	}
550	
551	export interface CodexHookReduceCounters {
552	  readonly eventsSeen: number;
553	  /** Payload was not an object, or carried no `session_id`. Counted, skipped. */
554	  readonly eventsUnusable: number;
555	  /** `agent_id` present but not a non-empty string. Attributed to the root. */
556	  readonly agentIdMalformed: number;
557	  /** Events with no `agent_id` key at all — the main thread (C11). */
558	  readonly rootEvents: number;
559	  readonly agentEvents: number;
560	  readonly subagentStarts: number;
561	  readonly subagentStops: number;
562	}
563	
564	export interface CodexHookReduction {
565	  readonly states: ReadonlyMap<string, CodexThreadHookState>;
566	  readonly counters: CodexHookReduceCounters;
567	}
568	
569	interface MutableReduceCounters {
570	  eventsSeen: number;
571	  eventsUnusable: number;
572	  agentIdMalformed: number;
573	  rootEvents: number;
574	  agentEvents: number;
575	  subagentStarts: number;
576	  subagentStops: number;
577	}
578	
579	function emptyReduceCounters(): MutableReduceCounters {
580	  return {
581	    eventsSeen: 0,
582	    eventsUnusable: 0,
583	    agentIdMalformed: 0,
584	    rootEvents: 0,
585	    agentEvents: 0,
586	    subagentStarts: 0,
587	    subagentStops: 0,
588	  };
589	}
590	
591	/**
592	 * Fold one hook event into a thread-keyed state map.
593	 *
594	 * Attribution is C11, and absence of `agent_id` is the signal: the key present
595	 * names the subagent's thread, the key absent means the root, whose id is the
596	 * payload's `session_id`. Nothing here compares against a literal `"main"`.
597	 *
598	 * `SubagentStop` — and `Stop`, and `SessionEnd` — clear the open tool calls and
599	 * do not touch the state. That is the whole of D0.1's second sentence, and the
600	 * `resume-twice-v1` test is what holds it in place.
601	 */
602	function applyCodexHookEvent(
603	  states: Map<string, MutableHookState>,
604	  event: CodexHookEvent,
605	  counters: MutableReduceCounters,
606	): void {
607	  counters.eventsSeen += 1;
608	
609	  const payload = asObject(event.payload);
610	  if (payload === null) {
611	    counters.eventsUnusable += 1;
612	    return;
613	  }
614	  const sessionId = nonEmptyString(payload['session_id']);
615	  if (sessionId === null) {
616	    counters.eventsUnusable += 1;
617	    return;
618	  }
619	
620	  const hasAgentKey = 'agent_id' in payload;
621	  const agentId = nonEmptyString(payload['agent_id']);
622	  if (hasAgentKey && agentId === null) counters.agentIdMalformed += 1;
623	
624	  const threadId = agentId ?? sessionId;
625	  const attributedBy: 'agent_id' | 'session_id' = agentId === null ? 'session_id' : 'agent_id';
626	  if (agentId === null) counters.rootEvents += 1;
627	  else counters.agentEvents += 1;
628	
629	  let state = states.get(threadId);
630	  if (state === undefined) {
631	    state = {
632	      threadId,
633	      attributedBy,
634	      lastEventMs: null,
635	      openToolUseIds: new Set<string>(),
636	      subagentStarts: 0,
637	      subagentStops: 0,
638	      events: 0,
639	    };
640	    states.set(threadId, state);
641	  }
642	
643	  state.events += 1;
644	  if (state.lastEventMs === null || event.receivedAtMs > state.lastEventMs) {
645	    state.lastEventMs = event.receivedAtMs;
646	  }
647	
648	  const name = typeof payload['hook_event_name'] === 'string' ? payload['hook_event_name'] : '';
649	  const toolUseId = nonEmptyString(payload['tool_use_id']);
650	
651	  if (name === 'PreToolUse' && toolUseId !== null) {
652	    state.openToolUseIds.add(toolUseId);
653	  } else if (name === 'PostToolUse' && toolUseId !== null) {
654	    state.openToolUseIds.delete(toolUseId);
655	  } else if (CODEX_IN_FLIGHT_CLEARING_EVENTS.has(name)) {
656	    // D0.1: this CLEARS IN FLIGHT and marks nothing dead. A stop is per turn.
657	    state.openToolUseIds.clear();
658	  }
659	
660	  if (name === 'SubagentStart') {
661	    state.subagentStarts += 1;
662	    counters.subagentStarts += 1;
663	  } else if (name === 'SubagentStop') {
664	    state.subagentStops += 1;
665	    counters.subagentStops += 1;
666	  }
667	}
668	
669	/** Fold a whole stream. Order-independent for `lastEventMs`, by construction. */
670	export function reduceCodexHookEvents(events: readonly CodexHookEvent[]): CodexHookReduction {
671	  const states = new Map<string, MutableHookState>();
672	  const counters = emptyReduceCounters();
673	  for (const event of events) applyCodexHookEvent(states, event, counters);
674	  return { states: freezeStates(states), counters };
675	}
676	
677	function freezeStates(
678	  states: ReadonlyMap<string, MutableHookState>,
679	): ReadonlyMap<string, CodexThreadHookState> {
680	  const out = new Map<string, CodexThreadHookState>();
681	  for (const [id, s] of states) {
682	    out.set(id, {
683	      threadId: s.threadId,
684	      attributedBy: s.attributedBy,
685	      lastEventMs: s.lastEventMs,
686	      openToolUseIds: new Set(s.openToolUseIds),
687	      subagentStarts: s.subagentStarts,
688	      subagentStops: s.subagentStops,
689	      events: s.events,
690	    });
691	  }
692	  return out;
693	}
694	
695	// ---------------------------------------------------------------------------
696	// The rule
697	// ---------------------------------------------------------------------------
698	
699	/**
700	 * The threads liveness is asked about. A {@link CodexThread} satisfies this
701	 * structurally, so a caller hands the parser's output straight in.
702	 */
703	export interface CodexLivenessThread {
704	  readonly threadId: string;
705	  /** The ROOT thread's id. Equal to `threadId` on a root (C11). */
706	  readonly sessionId: string;
707	  /** The owning transcript's last write. Corroboration only, never a start. */
708	  readonly mtimeMs?: number | null;
709	}
710	
711	export interface CodexLivenessInput {
712	  readonly threads: readonly CodexLivenessThread[];
713	  readonly hookEvents?: readonly CodexHookEvent[];
714	  /** Omitted = the lock half of D0.1 was never evaluated (`lockDirMissing`). */
715	  readonly lockScan?: CodexLockScan;
716	  /** Supplied only to compute {@link CodexLivenessReport.join}. */
717	  readonly toolCalls?: readonly CodexToolCall[];
718	}
719	
720	export interface CodexLivenessCounters extends CodexHookReduceCounters {
721	  /** Hook states whose thread is not among {@link CodexLivenessInput.threads}. */
722	  readonly hookStatesWithoutThread: number;
723	  /** Threads the tap said nothing about; the lock or mtime decided them. */
724	  readonly threadsWithoutHookEvents: number;
725	  readonly lockDirMissing: boolean;
726	  /** Entries the lock scan declined to read as thread ids. */
727	  readonly locksSkipped: number;
728	  /** Lock files naming a thread that is not among the supplied threads. */
729	  readonly locksWithoutThread: number;
730	  readonly degraded: number;
731	  readonly dead: number;
732	}
733	
734	export interface CodexLivenessReport {
735	  readonly threads: readonly CodexLiveness[];
736	  readonly counters: CodexLivenessCounters;
737	  readonly join: CodexHookJoinCounters;
738	}
739	
740	/**
741	 * Apply D0.1 to every supplied thread against an already-reduced tap.
742	 *
743	 * **This is the ONLY place a `CodexLiveness` is built**, and it is exported for
744	 * that reason rather than for its own sake: {@link computeCodexLiveness} and
745	 * {@link CodexLivenessEngine} both go through it. A second loop applying the
746	 * same rule is this repository's recorded module-boundary defect — two
747	 * internally consistent implementations that disagree, with nothing failing —
748	 * and a liveness engine is exactly where it would not be noticed.
749	 *
750	 * Pure. `now` is a number here, taken once by the caller, so every thread in
751	 * one report is decided against the same instant.
752	 */
753	export function renderCodexLiveness(
754	  threads: readonly CodexLivenessThread[],
755	  states: ReadonlyMap<string, CodexThreadHookState>,
756	  lockScan: CodexLockScan | undefined,
757	  now: number,
758	  thresholdMs: number,
759	): { threads: readonly CodexLiveness[]; counters: Omit<CodexLivenessCounters, keyof CodexHookReduceCounters> } {
760	  const lockKnown = lockScan !== undefined && lockScan.exists && lockScan.error === null;
761	  const lockedThreads = new Set(lockKnown ? lockScan.threadIds : []);
762	  const threadIds = new Set(threads.map((t) => t.threadId));
763	
764	  let threadsWithoutHookEvents = 0;
765	  let degraded = 0;
766	  let dead = 0;
767	
768	  const out: CodexLiveness[] = [];
769	  for (const thread of threads) {
770	    const state = states.get(thread.threadId);
771	    const lastHookEventMs = state?.lastEventMs ?? null;
772	    const lastMtimeMs = thread.mtimeMs ?? null;
773	    const lockPresent = lockedThreads.has(thread.threadId);
774	
775	    const hookSeen = lastHookEventMs !== null;
776	    const hookRecent = lastHookEventMs !== null && now - lastHookEventMs <= thresholdMs;
777	    const mtimeKnown = lastMtimeMs !== null;
778	    const mtimeRecent = lastMtimeMs !== null && now - lastMtimeMs <= thresholdMs;
779	    if (!hookSeen) threadsWithoutHookEvents += 1;
780	
781	    const decided = decide({
782	      hookSeen,
783	      hookRecent,
784	      lockKnown,
785	      lockPresent,
786	      mtimeKnown,
787	      mtimeRecent,
788	    });
789	    if (decided.degraded !== undefined) degraded += 1;
790	    if (decided.state === 'dead') dead += 1;
791	
792	    out.push({
793	      threadId: thread.threadId,
794	      state: decided.state,
795	      lockPresent,
796	      lastHookEventMs,
797	      lastMtimeMs,
798	      inFlight: (state?.openToolUseIds.size ?? 0) > 0,
799	      ...(decided.degraded === undefined ? {} : { degraded: decided.degraded }),
800	    });
801	  }
802	
803	  let hookStatesWithoutThread = 0;
804	  for (const id of states.keys()) if (!threadIds.has(id)) hookStatesWithoutThread += 1;
805	  let locksWithoutThread = 0;
806	  for (const id of lockedThreads) if (!threadIds.has(id)) locksWithoutThread += 1;
807	
808	  return {
809	    threads: out,
810	    counters: {
811	      hookStatesWithoutThread,
812	      threadsWithoutHookEvents,
813	      lockDirMissing: !lockKnown,
814	      locksSkipped: lockScan?.skipped.length ?? 0,
815	      locksWithoutThread,
816	      degraded,
817	      dead,
818	    },
819	  };
820	}
821	
822	/**
823	 * The D0.1 rule over a whole stream in one call: reduce the tap, apply the
824	 * table, count the join.
825	 *
826	 * Pure: every input is a value and the only clock is
827	 * {@link CodexLivenessDeps.now}, called exactly once.
828	 */
829	export function computeCodexLiveness(
830	  input: CodexLivenessInput,
831	  deps: CodexLivenessDeps,
832	): CodexLivenessReport {
833	  const events = input.hookEvents ?? [];
834	  const reduction = reduceCodexHookEvents(events);
835	  const rendered = renderCodexLiveness(
836	    input.threads,
837	    reduction.states,
838	    input.lockScan,
839	    deps.now(),
840	    deps.livenessThresholdMs,
841	  );
842	
843	  return {
844	    threads: rendered.threads,
845	    counters: { ...reduction.counters, ...rendered.counters },
846	    join: joinCodexHookToolIds(events, input.toolCalls ?? []),
847	  };
848	}
849	
850	interface DecisionInput {
851	  readonly hookSeen: boolean;
852	  readonly hookRecent: boolean;
853	  readonly lockKnown: boolean;
854	  readonly lockPresent: boolean;
855	  /** An mtime was supplied at all — distinct from it being recent. */
856	  readonly mtimeKnown: boolean;
857	  readonly mtimeRecent: boolean;
858	}
859	
860	interface Decision {
861	  readonly state: CodexLiveness['state'];
862	  readonly degraded: CodexLivenessDegradation | undefined;
863	}
864	
865	/**
866	 * The state table, and the only place a state is chosen.
867	 *
868	 * Extracted so the four rows sit within one screen of each other and so a
869	 * mutation to any one of them is a one-line diff — which is what made the
870	 * `AND` to `OR` mutation test cheap enough to run.
871	 */
872	function decide(input: DecisionInput): Decision {
873	  // Row 1. The primary tap answered. Nothing is degraded.
874	  if (input.hookRecent) return { state: 'live', degraded: undefined };
875	
876	  // Row 2. D0.1's lock conjunct could not be evaluated at all. We do not get
877	  // to call anything dead on half a rule, so mtime answers or nothing does.
878	  if (!input.lockKnown) {
879	    return {
880	      state: input.mtimeRecent ? 'idle' : 'unknown',
881	      // `mtimeOnly` means the mtime was the only evidence there was, so it is
882	      // only honest when there WAS an mtime and there were no hook events.
883	      // Otherwise the missing lock directory is the thing to name.
884	      degraded: !input.hookSeen && input.mtimeKnown ? 'mtimeOnly' : 'lockDirMissing',
885	    };
886	  }
887	
888	  const degraded: CodexLivenessDegradation | undefined = input.hookSeen ? undefined : 'noHookEvents';
889	
890	  // Row 3. The lock is there. Evidence of life, not proof — but D0.1 requires
891	  // the lock to be GONE, so this thread is not dead whatever the tap says.
892	  if (input.lockPresent) return { state: 'idle', degraded };
893	
894	  // Row 4. D0.1, both conjuncts: the lock is gone AND no hook event arrived
895	  // inside the window. This is the only branch that returns 'dead'.
896	  return { state: 'dead', degraded };
897	}
898	
899	// ---------------------------------------------------------------------------
900	// The polling seam
901	// ---------------------------------------------------------------------------
902	
903	/** A registered poll trigger. `stop` must be idempotent. */
904	export interface CodexPollTriggerHandle {
905	  stop(): void;
906	}
907	
908	/**
909	 * Registers `run` to be invoked roughly every `intervalMs`.
910	 *
911	 * Injected because no timer may live in this file: a liveness test that waits
912	 * on a real interval measures the machine it ran on. Tests supply a handle they
913	 * fire by hand. `CodexLivenessDeps` in `types.ts` declares `now` and the
914	 * threshold and does not declare this — and no work package may edit that
915	 * file — so it is declared here and composed into the engine's options.
916	 */
917	export type CodexPollTrigger = (run: () => void, intervalMs: number) => CodexPollTriggerHandle;
918	
919	/** What one poll reads from the world. Everything time-varying comes in here. */
920	export interface CodexLivenessSample {
921	  readonly threads: readonly CodexLivenessThread[];
922	  readonly lockScan?: CodexLockScan;
923	  readonly toolCalls?: readonly CodexToolCall[];
924	}
925	
926	export interface CodexLivenessEngineOptions extends CodexLivenessDeps {
927	  /** Read at every poll. The lock scan and the thread list both move. */
928	  readonly sample: () => CodexLivenessSample;
929	  readonly pollIntervalMs?: number;
930	  /** Omitted = {@link CodexLivenessEngine.start} registers nothing. */
931	  readonly pollTrigger?: CodexPollTrigger;
932	  /** Called after every poll. May throw; the throw is counted, never rethrown. */
933	  readonly onUpdate?: (report: CodexLivenessReport) => void;
934	}
935	
936	/**
937	 * Holds the hook reduction across polls and applies D0.1 on demand.
938	 *
939	 * The hook tap is a PUSH source and the lock directory is a PULL one, so the
940	 * engine is both: {@link CodexLivenessEngine.ingest} folds an event as it
941	 * arrives, and {@link CodexLivenessEngine.poll} re-reads the locks and
942	 * re-applies the rule. Nothing accumulates with session length — the reduction
943	 * is a fixed-size record per thread plus the open tool-call ids, which a
944	 * `PostToolUse` removes.
945	 */
946	export class CodexLivenessEngine {
947	  private readonly options: CodexLivenessEngineOptions;
948	  private readonly states = new Map<string, MutableHookState>();
949	  private readonly counters = emptyReduceCounters();
950	  private handle: CodexPollTriggerHandle | undefined;
951	  private last: CodexLivenessReport | undefined;
952	  private updateFailures = 0;
953	
954	  constructor(options: CodexLivenessEngineOptions) {
955	    this.options = options;
956	  }
957	
958	  /** One hook event from the loopback listener. Never throws (G2). */
959	  ingest(event: CodexHookEvent): void {
960	    applyCodexHookEvent(this.states, event, this.counters);
961	  }
962	
963	  /**
964	   * Re-read the locks and re-apply D0.1 against the reduction held so far.
965	   *
966	   * Goes through {@link renderCodexLiveness} — the same function
967	   * {@link computeCodexLiveness} calls — so the engine cannot drift from the
968	   * pure rule. The clock is read ONCE per poll, so every thread in one report
969	   * is decided against the same instant.
970	   */
971	  poll(): CodexLivenessReport {
972	    const sample = this.options.sample();
973	    const rendered = renderCodexLiveness(
974	      sample.threads,
975	      freezeStates(this.states),
976	      sample.lockScan,
977	      this.options.now(),
978	      this.options.livenessThresholdMs,
979	    );
980	
981	    const report: CodexLivenessReport = {
982	      threads: rendered.threads,
983	      counters: { ...this.counters, ...rendered.counters },
984	      // The engine's events were folded by `ingest` and not retained, so a
985	      // join over them is not available here. It is reported as zeroes rather
986	      // than omitted, and `hookIdsSeen: 0` says plainly that nothing was
987	      // counted — a silent absence is the class rule 18 exists for.
988	      join: joinCodexHookToolIds([], sample.toolCalls ?? []),
989	    };
990	
991	    this.last = report;
992	    if (this.options.onUpdate !== undefined) {
993	      try {
994	        this.options.onUpdate(report);
995	      } catch {
996	        this.updateFailures += 1;
997	      }
998	    }
999	    return report;
1000	  }
1001	
1002	  /** Register the trigger, if one was given, and poll once immediately. */
1003	  start(): void {
1004	    if (this.options.pollTrigger !== undefined && this.handle === undefined) {
1005	      this.handle = this.options.pollTrigger(
1006	        () => {
1007	          this.poll();
1008	        },
1009	        this.options.pollIntervalMs ?? DEFAULT_CODEX_POLL_INTERVAL_MS,
1010	      );
1011	    }
1012	    this.poll();
1013	  }
1014	
1015	  stop(): void {
1016	    this.handle?.stop();
1017	    this.handle = undefined;
1018	  }
1019	
1020	  get latest(): CodexLivenessReport | undefined {
1021	    return this.last;
1022	  }
1023	
1024	  get onUpdateFailures(): number {
1025	    return this.updateFailures;
1026	  }
1027	}
