1	/**
2	 * DoD 2.1 — Codex data-root resolution and transcript discovery.
3	 *
4	 * G6: nothing here reads a live Codex data root. Every case points at a
5	 * directory this file created, or at the committed corpus, and the one case
6	 * that lets `os.homedir()` decide fakes the home first and asserts the negative
7	 * control fails.
8	 */
9	
10	import {
11	  cpSync,
12	  existsSync,
13	  mkdirSync,
14	  mkdtempSync,
15	  readdirSync,
16	  realpathSync,
17	  rmSync,
18	  statSync,
19	  writeFileSync,
20	} from 'node:fs';
21	import { tmpdir } from 'node:os';
22	import { dirname, join, resolve, sep } from 'node:path';
23	import { fileURLToPath } from 'node:url';
24	
25	import { afterAll, describe, expect, it } from 'vitest';
26	
27	import {
28	  CODEX_DAY_DEPTH,
29	  CODEX_HOME_VAR,
30	  CODEX_LOCK_DIR_NAME,
31	  CODEX_ROLLOUT_FILE_RE,
32	  CodexLocator,
33	  locateCodex,
34	  resolveCodexRoot,
35	} from './locate.js';
36	import type { CodexLocateDirent, CodexLocateFs, CodexLocateLogRecord, CodexLocateStats } from './locate.js';
37	import {
38	  CODEX_NEVER_OPEN_DIR_NAMES,
39	  CODEX_NEVER_OPEN_NAMES,
40	  CODEX_NEVER_OPEN_SUFFIXES,
41	  isNeverOpen,
42	} from './never-open.js';
43	
44	const HERE = dirname(fileURLToPath(import.meta.url));
45	const REPO_ROOT = resolve(HERE, '..', '..');
46	const CORPUS = join(REPO_ROOT, 'fixtures', 'codex-0.151.0-alpha.7.2');
47	
48	/** The platform variable `os.homedir()` actually reads. THIS is the one to fake. */
49	const HOME_VAR = process.platform === 'win32' ? 'USERPROFILE' : 'HOME';
50	/** The one that does NOT decide the answer on this platform — the decoy. */
51	const DECOY_VAR = process.platform === 'win32' ? 'HOME' : 'USERPROFILE';
52	
53	const tempDirs: string[] = [];
54	
55	function tmp(prefix: string): string {
56	  // realpath: CI runners hand back 8.3 short components (`RUNNER~1`), which
57	  // break the path comparisons this suite makes.
58	  const dir = mkdtempSync(join(realpathSync.native(tmpdir()), prefix));
59	  tempDirs.push(dir);
60	  return dir;
61	}
62	
63	afterAll(() => {
64	  for (const dir of tempDirs) rmSync(dir, { recursive: true, force: true });
65	});
66	
67	/**
68	 * Independent enumeration of a tree's rollout files, by a different route from
69	 * the one under test: one flat recursive `readdirSync` and a string test,
70	 * against `locateCodex`'s depth-first walk and its regex.
71	 */
72	function expectedRollouts(root: string): string[] {
73	  const sessions = join(root, 'sessions');
74	  const entries = readdirSync(sessions, { recursive: true, encoding: 'utf8' });
75	  return entries
76	    .filter((rel) => {
77	      const name = rel.split(/[\\/]/).pop() ?? '';
78	      return name.startsWith('rollout-') && name.endsWith('.jsonl');
79	    })
80	    .map((rel) => join(sessions, rel))
81	    .sort();
82	}
83	
84	/** An fs seam that records every path handed to the filesystem. */
85	function recordingFs(): { fs: CodexLocateFs; touched: string[] } {
86	  const touched: string[] = [];
87	  const fs: CodexLocateFs = {
88	    statSync: (path): CodexLocateStats => {
89	      touched.push(path);
90	      return statSync(path);
91	    },
92	    readdirSync: (path): CodexLocateDirent[] => {
93	      touched.push(path);
94	      return readdirSync(path, { withFileTypes: true });
95	    },
96	  };
97	  return { fs, touched };
98	}
99	
100	/** Run `fn` with `process.env` patched, and restore it whatever happens. */
101	function withEnv(patch: Record<string, string | undefined>, fn: () => void): void {
102	  const saved: Record<string, string | undefined> = {};
103	  for (const key of Object.keys(patch)) saved[key] = process.env[key];
104	  try {
105	    for (const [key, value] of Object.entries(patch)) {
106	      if (value === undefined) delete process.env[key];
107	      else process.env[key] = value;
108	    }
109	    fn();
110	  } finally {
111	    for (const [key, value] of Object.entries(saved)) {
112	      if (value === undefined) delete process.env[key];
113	      else process.env[key] = value;
114	    }
115	  }
116	}
117	
118	/** A `<home>/.codex/sessions/<day>/rollout-*.jsonl` tree. */
119	function plantRoot(options: { day?: string; files?: string[] } = {}): {
120	  home: string;
121	  root: string;
122	  day: string;
123	  planted: string[];
124	} {
125	  const home = tmp('cx-locate-home-');
126	  const root = join(home, '.codex');
127	  // A day that is emphatically not today: DoD 2.1's walk must not compose a
128	  // date from a clock, and a fixture dated today could not tell the difference.
129	  const day = options.day ?? join('2019', '01', '02');
