1	/**
2	 * `src/codex/fingerprint.ts` — PLAN.md v0.6.0 Phase 2, DoD 2.2.
3	 *
4	 * Shaped after `src/opencode/fingerprint.test.ts` and `src/parser/corpus.test.ts`,
5	 * for the reason those two share: the anchor's whole meaning is "the release
6	 * whose captured corpus proved the structure", so it is asserted against the
7	 * corpus on disk rather than against itself. Moving `PINNED_CODEX_VERSION`
8	 * without harvesting fails here.
9	 *
10	 * Three properties this file is built to have, each because the repository has
11	 * shipped the absence of it:
12	 *
13	 *  - **Every refusal asserts its EXACT code and field.** A test that only
14	 *    checked "something was rejected" keeps passing while the rejection moves
15	 *    to the wrong cause, which is exactly how a fixture ends up proving
16	 *    nothing.
17	 *  - **Every refusal fixture has an unmutated CONTROL.** Without one, the
18	 *    slicing that built the fixture could be what refuses.
19	 *  - **The version half and the structural half cannot be confused.** Every
20	 *    structural fixture carries the anchor version untouched; every version
21	 *    fixture is structurally perfect. `fixtures/synthetic-codex-structure/README.md`
22	 *    records both directions, and this file asserts them rather than trusting
23	 *    the README - see the describe block "the structural half and the version
24	 *    half cannot be confused".
25	 *
26	 * Nothing here writes anything anywhere. Every input is a committed file.
27	 */
28	
29	import { readFileSync, readdirSync } from 'node:fs';
30	import { fileURLToPath } from 'node:url';
31	import { join } from 'node:path';
32	
33	import { describe, expect, it } from 'vitest';
34	
35	import {
36	  CODEX_CALL_PAYLOAD_TYPES,
37	  CODEX_DIALECT_BY_NAMESPACE,
38	  CODEX_DIALECT_SOURCE_ORDER,
39	  CODEX_RECORD_KEYS,
40	  CODEX_SESSION_META_FIELDS,
41	  CODEX_SPAWN_TOOL_NAME,
42	  CODEX_THREAD_SPAWN_JOIN_KEYS,
43	  CODEX_VERSION_WINDOW,
44	  PINNED_CODEX_VERSION,
45	  codexVersionWindow,
46	  fingerprintThread,
47	  isCodexVersionAccepted,
48	  parseCodexVersion,
49	} from './fingerprint.js';
50	import type { CodexMismatchCode } from './types.js';
51	
52	// ---------------------------------------------------------------------------
53	// Corpora on disk
54	// ---------------------------------------------------------------------------
55	
56	const FIXTURES = fileURLToPath(new URL('../../fixtures/', import.meta.url));
57	
58	/**
59	 * The anchor's corpus directory name, DERIVED from the constant. Writing
60	 * `codex-0.151.0-alpha.7.2` here as a literal would make the two agree by
61	 * coincidence rather than by construction, and the constant could then move
62	 * without this file noticing.
63	 */
64	const ANCHOR_CORPUS = `codex-${PINNED_CODEX_VERSION}`;
65	const ANCHOR_DIR = join(FIXTURES, ANCHOR_CORPUS);
66	const MUTATIONS_DIR = join(FIXTURES, 'synthetic-codex-structure');
67	
68	/** Every rollout transcript under a corpus directory. Hook streams excluded. */
69	function transcripts(dir: string): string[] {
70	  const out: string[] = [];
71	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
72	    const full = join(dir, entry.name);
73	    if (entry.isDirectory()) {
74	      out.push(...transcripts(full));
75	      continue;
76	    }
77	    if (entry.name.startsWith('rollout-') && entry.name.endsWith('.jsonl')) out.push(full);
78	  }
79	  return out.sort();
80	}
81	
82	function readRecords(path: string): unknown[] {
83	  return readFileSync(path, 'utf8')
84	    .split('\n')
85	    .filter((line) => line.length > 0)
86	    .map((line) => JSON.parse(line) as unknown);
87	}
