662	
663	// ---------------------------------------------------------------------------
664	// agent_path — the field that is deliberately not asserted
665	// ---------------------------------------------------------------------------
666	
667	describe('agent_path is deliberately outside the fingerprint (spec C3)', () => {
668	  it('is one of TWO join keys, either of which is enough (Amendment 2026-09-03)', () => {
669	    // The amendment did not put agent_path into a REQUIRED list — it made the
670	    // pair an OR. A subagent carrying either key is joinable by one dialect
