679	    for (const record of records) {
680	      const r = record as { type: string; payload: Record<string, unknown> };
681	      if (r.type !== 'session_meta') continue;
682	      if (r.payload['thread_source'] !== 'subagent') continue;
683	      const src = r.payload['source'] as { subagent: { thread_spawn: Record<string, unknown> } };
684	      expect(Object.hasOwn(src.subagent.thread_spawn, 'depth')).toBe(false);
685	    }
686	    expect(fingerprintThread(records).ok).toBe(true);
687	  });
688	
689	  it('accepts a subagent with agent_path but no parent_thread_id — one key is enough', () => {
690	    const records = mutation('subagent-spawn-no-parent-thread-id.jsonl');
691	    for (const record of records) {
692	      const r = record as { type: string; payload: Record<string, unknown> };
693	      if (r.type !== 'session_meta') continue;
