723	});
724	
725	// ---------------------------------------------------------------------------
726	// Hostile input: a refusal is returned, never thrown
727	// ---------------------------------------------------------------------------
728	
729	describe('never throws: a refusal is a value (G3)', () => {
730	  const HOSTILE: [string, unknown[], CodexMismatchCode][] = [
731	    ['an empty thread', [], 'sessionMetaMissing'],
732	    ['a null record', [null], 'recordShapeMismatch'],
733	    ['a string record', ['session_meta'], 'recordShapeMismatch'],
734	    ['an empty object', [{}], 'recordShapeMismatch'],
