786	  it('accepts a corpus transcript under a neighbouring anchor', () => {
787	    const path = CORPUS_TRANSCRIPTS[0]!;
788	    expect(fingerprintThread(readRecords(path), { anchor: '0.152.4' }).ok).toBe(true);
789	  });
790	
