235	    const callId = str(r.payload['call_id']);
236	    if (callId === null) continue;
237	    const name = str(r.payload['name']) ?? '';
238	    const raw = outputs.get(callId);
239	    const truncated = raw !== undefined && raw.length > PREVIEW_BYTES;
240	    if (truncated) payloadsTruncated += 1;
241	    const preview = raw === undefined ? undefined : raw.slice(0, PREVIEW_BYTES);
242	    const completion = completions.find((c) => c.ordinal > r.ordinal);
243	    const itemId = completion === undefined ? null : str(completion.item?.['id']);
244	    const itemType = completion === undefined ? null : str(completion.item?.['type']);
245	
246	    toolCalls.push({
