292	      activityAgentPath: opt<string>(activityItem, 'agent_path'),
293	      activityAgentThreadId: activityItem === undefined ? null : str(activityItem['agent_thread_id']),
294	      threadId: str(payload['id']) ?? '',
295	      file: path.basename(file),
296	      ordinal: r.ordinal,
297	      callId,
298	      itemId,
299	      namespace: opt<string>(r.payload, 'namespace'),
300	      requestedTaskName: str(args['task_name']),
301	      outputTaskName,
302	      outputAgentId,
303	      outputNickname: parsed === undefined ? null : str(parsed['nickname']),
304	      // NOT resolved here. `parse.ts` sees one thread at a time and cannot know
