374	  return {
375	    threadSpawn: {
376	      present: spawn !== undefined,
377	      agentPath: opt<string>(spawn, 'agent_path'),
378	      agentNickname: opt<string>(spawn, 'agent_nickname'),
379	      agentRole: opt<string>(spawn, 'agent_role'),
380	      parentThreadId: opt<string>(spawn, 'parent_thread_id'),
381	      depth: opt<number>(spawn, 'depth'),
